  1	package policy
  2	
  3	import (
  4		"fmt"
  5		"math"
  6		"sort"
  7		"strconv"
  8		"strings"
  9		"time"
 10	
 11		"github.com/kopia/kopia/snapshot"
 12	)
 13	
 14	const (
 15		// keep all snapshots younger than this.
 16		retainIncompleteSnapshotsYoungerThan = 4 * time.Hour
 17	
 18		// minimal number of incomplete snapshots to keep.
 19		retainIncompleteSnapshotMinimumCount = 3
 20	)
 21	
 22	// RetentionPolicy describes snapshot retention policy.
 23	type RetentionPolicy struct {
 24		KeepLatest               *OptionalInt  `json:"keepLatest,omitempty"`
 25		KeepHourly               *OptionalInt  `json:"keepHourly,omitempty"`
 26		KeepDaily                *OptionalInt  `json:"keepDaily,omitempty"`
 27		KeepWeekly               *OptionalInt  `json:"keepWeekly,omitempty"`
 28		KeepMonthly              *OptionalInt  `json:"keepMonthly,omitempty"`
 29		KeepAnnual               *OptionalInt  `json:"keepAnnual,omitempty"`
 30		IgnoreIdenticalSnapshots *OptionalBool `json:"ignoreIdenticalSnapshots,omitempty"`
 31	}
 32	
 33	// RetentionPolicyDefinition specifies which policy definition provided the value of a particular field.
 34	type RetentionPolicyDefinition struct {
 35		KeepLatest               snapshot.SourceInfo `json:"keepLatest,omitempty"`
 36		KeepHourly               snapshot.SourceInfo `json:"keepHourly,omitempty"`
 37		KeepDaily                snapshot.SourceInfo `json:"keepDaily,omitempty"`
 38		KeepWeekly               snapshot.SourceInfo `json:"keepWeekly,omitempty"`
 39		KeepMonthly              snapshot.SourceInfo `json:"keepMonthly,omitempty"`
 40		KeepAnnual               snapshot.SourceInfo `json:"keepAnnual,omitempty"`
 41		IgnoreIdenticalSnapshots snapshot.SourceInfo `json:"ignoreIdenticalSnapshots,omitempty"`
 42	}
 43	
 44	// ComputeRetentionReasons computes the reasons why each snapshot is retained, based on
 45	// the settings in retention policy and stores them in RetentionReason field.
 46	func (r *RetentionPolicy) ComputeRetentionReasons(manifests []*snapshot.Manifest) {
 47		if len(manifests) == 0 {
 48			return
 49		}
 50	
 51		// compute max time across all and complete snapshots
 52		var (
 53			maxCompleteStartTime time.Time
 54			maxStartTime         time.Time
 55		)
 56	
 57		for _, m := range manifests {
 58			if m.StartTime.ToTime().After(maxStartTime) {
 59				maxStartTime = m.StartTime.ToTime()
 60			}
 61	
 62			if m.IncompleteReason == "" && m.StartTime.ToTime().After(maxCompleteStartTime) {
 63				maxCompleteStartTime = m.StartTime.ToTime()
 64			}
 65		}
 66	
 67		maxTime := maxCompleteStartTime.Add(365 * 24 * time.Hour)
 68	
 69		cutoffTime := func(setting *OptionalInt, add func(time.Time, int) time.Time) time.Time {
 70			if setting != nil {
 71				return add(maxCompleteStartTime, int(*setting))
 72			}
 73	
 74			return maxTime
 75		}
 76	
 77		cutoff := &cutoffTimes{
 78			annual:  cutoffTime(r.KeepAnnual, yearsAgo),
 79			monthly: cutoffTime(r.KeepMonthly, monthsAgo),
 80			daily:   cutoffTime(r.KeepDaily, daysAgo),
 81			hourly:  cutoffTime(r.KeepHourly, hoursAgo),
 82			weekly:  cutoffTime(r.KeepWeekly, weeksAgo),
 83		}
 84	
 85		ids := make(map[string]bool)
 86		idCounters := make(map[string]int)
 87	
 88		// sort manifests in descending time order (most recent first)
 89		sorted := snapshot.SortByTime(manifests, true)
 90	
 91		// apply retention reasons to complete snapshots
 92		for i, s := range sorted {
 93			if s.IncompleteReason == "" {
 94				s.RetentionReasons = r.getRetentionReasons(i, s, cutoff, ids, idCounters)
 95			} else {
 96				s.RetentionReasons = []string{}
 97			}
 98		}
 99	
100		// attach 'retention reason' tag to incomplete snapshots until we run into first complete one
101		// or we have enough incomplete ones and we run into an old one.
102		for i, s := range sorted {
103			if s.IncompleteReason == "" {
104				break
105			}
106	
107			age := maxStartTime.Sub(s.StartTime.ToTime())
108			// retain incomplete snapshots below certain age and below maximum count.
109			if age < retainIncompleteSnapshotsYoungerThan || i < retainIncompleteSnapshotMinimumCount {
110				s.RetentionReasons = append(s.RetentionReasons, "incomplete")
111			} else {
112				break
113			}
114		}
115	}
116	
117	// EffectiveKeepLatest returns the number of "latest" snapshots to keep. If all
118	// retention values are set to 0 then returns MaxInt.
119	func (r *RetentionPolicy) EffectiveKeepLatest() *OptionalInt {
120		if r.KeepLatest.OrDefault(0)+r.KeepHourly.OrDefault(0)+r.KeepDaily.OrDefault(0)+r.KeepWeekly.OrDefault(0)+r.KeepMonthly.OrDefault(0)+r.KeepAnnual.OrDefault(0) == 0 {
121			return newOptionalInt(math.MaxInt)
122		}
123	
124		return r.KeepLatest
125	}
126	
127	func (r *RetentionPolicy) getRetentionReasons(i int, s *snapshot.Manifest, cutoff *cutoffTimes, ids map[string]bool, idCounters map[string]int) []string {
128		if s.IncompleteReason != "" {
129			return nil
130		}
131	
132		keepReasons := []string{}
133	
134		var zeroTime time.Time
135	
136		yyyy, wk := s.StartTime.ToTime().ISOWeek()
137	
138		effectiveKeepLatest := r.EffectiveKeepLatest()
139	
140		cases := []struct {
141			cutoffTime     time.Time
142			timePeriodID   string
143			timePeriodType string
144			max            *OptionalInt
145		}{
146			{zeroTime, strconv.Itoa(i), "latest", effectiveKeepLatest},
147			{cutoff.annual, s.StartTime.Format("2006"), "annual", r.KeepAnnual},
148			{cutoff.monthly, s.StartTime.Format("2006-01"), "monthly", r.KeepMonthly},
149			{cutoff.weekly, fmt.Sprintf("%04v-%02v", yyyy, wk), "weekly", r.KeepWeekly},
150			{cutoff.daily, s.StartTime.Format("2006-01-02"), "daily", r.KeepDaily},
151			{cutoff.hourly, s.StartTime.Format("2006-01-02 15"), "hourly", r.KeepHourly},
152		}
153	
154		for _, c := range cases {
155			if c.max == nil {
156				continue
157			}
158	
159			if s.StartTime.ToTime().Before(c.cutoffTime) {
160				continue
161			}
162	
163			if _, exists := ids[c.timePeriodID]; exists {
164				continue
165			}
166	
167			if idCounters[c.timePeriodType] < int(*c.max) {
168				ids[c.timePeriodID] = true
169				idCounters[c.timePeriodType]++
170				keepReasons = append(keepReasons, fmt.Sprintf("%v-%v", c.timePeriodType, idCounters[c.timePeriodType]))
171			}
172		}
173	
174		SortRetentionTags(keepReasons)
175	
176		return keepReasons
177	}
178	
179	type cutoffTimes struct {
180		annual  time.Time
181		monthly time.Time
182		daily   time.Time
183		hourly  time.Time
184		weekly  time.Time
185	}
186	
187	func yearsAgo(base time.Time, n int) time.Time {
188		return base.AddDate(-n, 0, 0)
189	}
190	
191	func monthsAgo(base time.Time, n int) time.Time {
192		return base.AddDate(0, -n, 0)
193	}
194	
195	func daysAgo(base time.Time, n int) time.Time {
196		return base.AddDate(0, 0, -n)
197	}
198	
199	func weeksAgo(base time.Time, n int) time.Time {
200		return base.AddDate(0, 0, -n*7) //nolint:mnd
201	}
202	
203	func hoursAgo(base time.Time, n int) time.Time {
204		return base.Add(time.Duration(-n) * time.Hour)
205	}
206	
207	const (
208		defaultKeepLatest               = 10
209		defaultKeepHourly               = 48
210		defaultKeepDaily                = 7
211		defaultKeepWeekly               = 4
212		defaultKeepMonthly              = 24
213		defaultKeepAnnual               = 3
214		defaultIgnoreIdenticalSnapshots = false
215	)
216	
217	// Merge applies default values from the provided policy.
218	func (r *RetentionPolicy) Merge(src RetentionPolicy, def *RetentionPolicyDefinition, si snapshot.SourceInfo) {
219		mergeOptionalInt(&r.KeepLatest, src.KeepLatest, &def.KeepLatest, si)
220		mergeOptionalInt(&r.KeepHourly, src.KeepHourly, &def.KeepHourly, si)
221		mergeOptionalInt(&r.KeepDaily, src.KeepDaily, &def.KeepDaily, si)
222		mergeOptionalInt(&r.KeepWeekly, src.KeepWeekly, &def.KeepWeekly, si)
223		mergeOptionalInt(&r.KeepMonthly, src.KeepMonthly, &def.KeepMonthly, si)
224		mergeOptionalInt(&r.KeepAnnual, src.KeepAnnual, &def.KeepAnnual, si)
225		mergeOptionalBool(&r.IgnoreIdenticalSnapshots, src.IgnoreIdenticalSnapshots, &def.IgnoreIdenticalSnapshots, si)
226	}
227	
228	// CompactRetentionReasons returns compressed retention reasons given a list of retention reasons.
229	func CompactRetentionReasons(reasons []string) []string {
230		reasonsByPrefix := map[string][]int{}
231	
232		result := []string{}
233	
234		for _, r := range reasons {
235			prefix, suffix := prefixSuffix(r)
236	
237			n, err := strconv.Atoi(suffix)
238			if err != nil {
239				result = append(result, r)
240				continue
241			}
242	
243			reasonsByPrefix[prefix] = append(reasonsByPrefix[prefix], n)
244		}
245	
246		for prefix, v := range reasonsByPrefix {
247			result = appendRLE(result, prefix, v)
248		}
249	
250		SortRetentionTags(result)
251	
252		return result
253	}
254	
255	func prefixSuffix(s string) (prefix, suffix string) {
256		prefix, suffix, _ = strings.CutLast(s, "-")
257	
258		return prefix, suffix
259	}
260	
261	func appendRLE(out []string, prefix string, numbers []int) []string {
262		sort.Ints(numbers)
263	
264		runStart := numbers[0]
265		runEnd := numbers[0]
266	
267		appendRun := func() {
268			if runStart == runEnd {
269				out = append(out, fmt.Sprintf("%v-%v", prefix, runStart))
270			} else {
271				out = append(out, fmt.Sprintf("%v-%v..%v", prefix, runStart, runEnd))
272			}
273		}
274	
275		for _, num := range numbers[1:] {
276			if num == runEnd+1 {
277				runEnd = num
278			} else {
279				appendRun()
280	
281				runStart = num
282				runEnd = runStart
283			}
284		}
285	
286		appendRun()
287	
288		return out
289	}
290	
291	// CompactPins returns compressed pins reasons given a list of pins.
292	func CompactPins(pins []string) []string {
293		cnt := map[string]int{}
294	
295		for _, p := range pins {
296			cnt[p]++
297		}
298	
299		result := []string{}
300	
301		for k := range cnt {
302			result = append(result, k)
303		}
304	
305		sort.Strings(result)
306	
307		return result
308	}
309	
310	// SortRetentionTags sorts the provided retention tags in canonical order.
311	func SortRetentionTags(tags []string) {
312		retentionPrefixSortValue := map[string]int{
313			"latest":  1,
314			"hourly":  2, //nolint:mnd
315			"daily":   3, //nolint:mnd
316			"weekly":  4, //nolint:mnd
317			"monthly": 5, //nolint:mnd
318			"annual":  6, //nolint:mnd
319		}
320	
321		sort.Slice(tags, func(i, j int) bool {
322			p1, s1 := prefixSuffix(tags[i])
323			p2, s2 := prefixSuffix(tags[j])
324	
325			if l, r := retentionPrefixSortValue[p1], retentionPrefixSortValue[p2]; l != r {
326				return l < r
327			}
328	
329			if l, r := p1, p2; l != r {
330				return p1 < p2
331			}
332	
333			return s1 < s2
334		})
335	}
336	package policy
337	
338	import (
339		"context"
340		"strings"
341	
342		"github.com/pkg/errors"
343	
344		"github.com/kopia/kopia/repo"
345		"github.com/kopia/kopia/repo/manifest"
346		"github.com/kopia/kopia/snapshot"
347	)
348	
349	// ApplyRetentionPolicy applies retention policy to a given source by deleting expired snapshots.
350	func ApplyRetentionPolicy(ctx context.Context, rep repo.RepositoryWriter, sourceInfo snapshot.SourceInfo, reallyDelete bool) ([]manifest.ID, error) {
351		// it is desired to not allow snapshots to be deleted by repository clients,
352		// while still maintain the ability to apply snapshot retention policies server-side.
353		if remote, ok := rep.(repo.RemoteRetentionPolicy); ok {
354			if sourceInfo.UserName == rep.ClientOptions().Username && sourceInfo.Host == rep.ClientOptions().Hostname {
355				// for repository clients, apply retention policy on the server.
356				log(ctx).Debug("applying retention policy on the server")
357	
358				//nolint:wrapcheck
359				return remote.ApplyRetentionPolicy(ctx, sourceInfo.Path, reallyDelete)
360			}
361		}
362	
363		snapshots, err := snapshot.ListSnapshots(ctx, rep, sourceInfo)
364		if err != nil {
365			return nil, errors.Wrap(err, "error listing snapshots")
366		}
367	
368		toDelete, err := getExpiredSnapshots(ctx, rep, snapshots)
369		if err != nil {
370			return nil, errors.Wrap(err, "unable to compute snapshots to delete")
371		}
372	
373		if reallyDelete {
374			for _, manifestID := range toDelete {
375				if err := rep.DeleteManifest(ctx, manifestID); err != nil {
376					return toDelete, errors.Wrapf(err, "error deleting manifest %v", manifestID)
377				}
378			}
379		}
380	
381		return toDelete, nil
382	}
383	
384	func getExpiredSnapshots(ctx context.Context, rep repo.Repository, snapshots []*snapshot.Manifest) ([]manifest.ID, error) {
385		var toDelete []manifest.ID
386	
387		for _, snapshotGroup := range snapshot.GroupBySource(snapshots) {
388			td, err := getExpiredSnapshotsForSource(ctx, rep, snapshotGroup)
389			if err != nil {
390				return nil, err
391			}
392	
393			toDelete = append(toDelete, td...)
394		}
395	
396		return toDelete, nil
397	}
398	
399	func getExpiredSnapshotsForSource(ctx context.Context, rep repo.Repository, snapshots []*snapshot.Manifest) ([]manifest.ID, error) {
400		src := snapshots[0].Source
401	
402		pol, _, _, err := GetEffectivePolicy(ctx, rep, src)
403		if err != nil {
404			return nil, err
405		}
406	
407		pol.RetentionPolicy.ComputeRetentionReasons(snapshots)
408	
409		var toDelete []manifest.ID
410	
411		for _, s := range snapshots {
412			if len(s.RetentionReasons) == 0 && len(s.Pins) == 0 {
413				log(ctx).Debugf("  deleting %v", s.StartTime)
414				toDelete = append(toDelete, s.ID)
415			} else {
416				log(ctx).Debugf("  keeping %v retention: [%v] pins: [%v]", s.StartTime.ToTime(), strings.Join(s.RetentionReasons, ","), strings.Join(s.Pins, ","))
417			}
418		}
419	
420		return toDelete, nil
421	}

