228	// CompactRetentionReasons returns compressed retention reasons given a list of retention reasons.
229	func CompactRetentionReasons(reasons []string) []string {
230		reasonsByPrefix := map[string][]int{}
231	
232		result := []string{}
233	
234		for _, r := range reasons {
235			prefix, suffix := prefixSuffix(r)
236	
237			n, err := strconv.Atoi(suffix)
238			if err != nil {
239				result = append(result, r)
240				continue
241			}
242	
243			reasonsByPrefix[prefix] = append(reasonsByPrefix[prefix], n)
244		}
245	
246		for prefix, v := range reasonsByPrefix {
247			result = appendRLE(result, prefix, v)
248		}
249	
250		SortRetentionTags(result)
251	
252		return result
253	}
254	
255	func prefixSuffix(s string) (prefix, suffix string) {
256		prefix, suffix, _ = strings.CutLast(s, "-")
257	
258		return prefix, suffix
259	}
260	
261	func appendRLE(out []string, prefix string, numbers []int) []string {
262		sort.Ints(numbers)
263	
264		runStart := numbers[0]
265		runEnd := numbers[0]
266	
267		appendRun := func() {
268			if runStart == runEnd {
269				out = append(out, fmt.Sprintf("%v-%v", prefix, runStart))
270			} else {
271				out = append(out, fmt.Sprintf("%v-%v..%v", prefix, runStart, runEnd))
272			}
273		}
274	
275		for _, num := range numbers[1:] {
276			if num == runEnd+1 {
277				runEnd = num
278			} else {
279				appendRun()
280	
281				runStart = num
282				runEnd = runStart
283			}
284		}
285	
286		appendRun()
287	
288		return out
289	}
290	
291	// CompactPins returns compressed pins reasons given a list of pins.
292	func CompactPins(pins []string) []string {
293		cnt := map[string]int{}
294	
295		for _, p := range pins {
296			cnt[p]++
297		}
298	
299		result := []string{}
300	
301		for k := range cnt {
302			result = append(result, k)
303		}
304	
305		sort.Strings(result)
306	
307		return result
308	}
309	
310	// SortRetentionTags sorts the provided retention tags in canonical order.
311	func SortRetentionTags(tags []string) {
312		retentionPrefixSortValue := map[string]int{
313			"latest":  1,
314			"hourly":  2, //nolint:mnd
315			"daily":   3, //nolint:mnd
316			"weekly":  4, //nolint:mnd
317			"monthly": 5, //nolint:mnd
318			"annual":  6, //nolint:mnd
319		}
320	
321		sort.Slice(tags, func(i, j int) bool {
322			p1, s1 := prefixSuffix(tags[i])
323			p2, s2 := prefixSuffix(tags[j])
324	
325			if l, r := retentionPrefixSortValue[p1], retentionPrefixSortValue[p2]; l != r {
326				return l < r
327			}
328	
329			if l, r := p1, p2; l != r {
330				return p1 < p2
331			}
332	
333			return s1 < s2
334		})
335	}
