349	// ApplyRetentionPolicy applies retention policy to a given source by deleting expired snapshots.
350	func ApplyRetentionPolicy(ctx context.Context, rep repo.RepositoryWriter, sourceInfo snapshot.SourceInfo, reallyDelete bool) ([]manifest.ID, error) {
351		// it is desired to not allow snapshots to be deleted by repository clients,
352		// while still maintain the ability to apply snapshot retention policies server-side.
353		if remote, ok := rep.(repo.RemoteRetentionPolicy); ok {
354			if sourceInfo.UserName == rep.ClientOptions().Username && sourceInfo.Host == rep.ClientOptions().Hostname {
355				// for repository clients, apply retention policy on the server.
356				log(ctx).Debug("applying retention policy on the server")
357	
358				//nolint:wrapcheck
359				return remote.ApplyRetentionPolicy(ctx, sourceInfo.Path, reallyDelete)
360			}
361		}
362	
363		snapshots, err := snapshot.ListSnapshots(ctx, rep, sourceInfo)
364		if err != nil {
365			return nil, errors.Wrap(err, "error listing snapshots")
366		}
367	
368		toDelete, err := getExpiredSnapshots(ctx, rep, snapshots)
369		if err != nil {
370			return nil, errors.Wrap(err, "unable to compute snapshots to delete")
371		}
372	
373		if reallyDelete {
374			for _, manifestID := range toDelete {
375				if err := rep.DeleteManifest(ctx, manifestID); err != nil {
376					return toDelete, errors.Wrapf(err, "error deleting manifest %v", manifestID)
377				}
378			}
379		}
380	
381		return toDelete, nil
382	}
383	
384	func getExpiredSnapshots(ctx context.Context, rep repo.Repository, snapshots []*snapshot.Manifest) ([]manifest.ID, error) {
385		var toDelete []manifest.ID
386	
387		for _, snapshotGroup := range snapshot.GroupBySource(snapshots) {
388			td, err := getExpiredSnapshotsForSource(ctx, rep, snapshotGroup)
389			if err != nil {
390				return nil, err
391			}
392	
393			toDelete = append(toDelete, td...)
394		}
395	
396		return toDelete, nil
397	}
398	
399	func getExpiredSnapshotsForSource(ctx context.Context, rep repo.Repository, snapshots []*snapshot.Manifest) ([]manifest.ID, error) {
400		src := snapshots[0].Source
401	
402		pol, _, _, err := GetEffectivePolicy(ctx, rep, src)
403		if err != nil {
404			return nil, err
405		}
406	
407		pol.RetentionPolicy.ComputeRetentionReasons(snapshots)
408	
409		var toDelete []manifest.ID
410	
411		for _, s := range snapshots {
412			if len(s.RetentionReasons) == 0 && len(s.Pins) == 0 {
413				log(ctx).Debugf("  deleting %v", s.StartTime)
414				toDelete = append(toDelete, s.ID)
415			} else {
416				log(ctx).Debugf("  keeping %v retention: [%v] pins: [%v]", s.StartTime.ToTime(), strings.Join(s.RetentionReasons, ","), strings.Join(s.Pins, ","))
417			}
418		}
419	
420		return toDelete, nil
421	}

