 795	// WriteContent saves a given content of data to a pack group with a provided name and returns a contentID
 796	// that's based on the contents of data written.
 797	func (bm *WriteManager) WriteContent(ctx context.Context, data gather.Bytes, prefix index.IDPrefix, comp compression.HeaderID) (ID, error) {
 798		t0 := timetrack.StartTimer()
 799		defer func() {
 800			bm.writeContentBytes.Observe(int64(data.Length()), t0.Elapsed())
 801		}()
 802	
 803		mp, mperr := bm.format.GetMutableParameters(ctx)
 804		if mperr != nil {
 805			return EmptyID, errors.Wrap(mperr, "mutable parameters")
 806		}
 807	
 808		if err := bm.maybeRetryWritingFailedPacksUnlocked(ctx); err != nil {
 809			return EmptyID, err
 810		}
 811	
 812		if err := prefix.ValidateSingle(); err != nil {
 813			return EmptyID, errors.Wrap(err, "invalid prefix")
 814		}
 815	
 816		var hashOutput [hashing.MaxHashSize]byte
 817	
 818		contentID, err := IDFromHash(prefix, bm.hashData(hashOutput[:0], data))
 819		if err != nil {
 820			return EmptyID, errors.Wrap(err, "invalid hash")
 821		}
 822	
 823		previousWriteTime := int64(-1)
 824	
 825		bm.mu.RLock()
 826		_, bi, err := bm.getContentInfoReadLocked(ctx, contentID)
 827		bm.mu.RUnlock()
 828	
 829		// content already tracked
 830		if err == nil {
 831			if !bi.Deleted {
 832				bm.deduplicatedContents.Add(1)
 833				bm.deduplicatedBytes.Add(int64(data.Length()))
 834	
 835				return contentID, nil
 836			}
 837	
 838			previousWriteTime = bi.TimestampSeconds
 839	
 840			contentlog.Log2(ctx, bm.log, "write-content-previously-deleted",
 841				contentparam.ContentID("cid", contentID),
 842				logparam.Int64("previousWriteTime", previousWriteTime))
 843		} else {
 844			contentlog.Log1(ctx, bm.log, "write-content-new",
 845				contentparam.ContentID("cid", contentID))
 846		}
 847	
 848		return contentID, bm.addToPackUnlocked(ctx, contentID, data, false, comp, previousWriteTime, mp)
 849	}
