  91			}
  92		}
  93	
  94		mp, mperr := m.formattingOptions.GetMutableParameters(ctx)
  95		if mperr != nil {
  96			return errors.Wrap(mperr, "mutable parameters")
  97		}
  98	
  99		dataShards, cleanupShards, err := tmpbld.BuildShards(mp.IndexVersion, true, DefaultIndexShardSize)
 100		if err != nil {
 101			return errors.Wrap(err, "unable to build index dataShards")
 102		}
 103	
 104		defer cleanupShards()
 105	
 106		var rnd [8]byte
 107	
 108		if _, err := rand.Read(rnd[:]); err != nil {
 109			return errors.Wrap(err, "error getting random session ID")
 110		}
 111	
 112		sessionID := fmt.Sprintf("s%x-c%v", rnd[:], len(dataShards))
 113	
 114		var data2 gather.WriteBuffer
 115		defer data2.Close()
 116	
 117		for _, data := range dataShards {
 118			data2.Reset()
 119	
 120			blobID, err := blobcrypto.Encrypt(m.enc.crypter, data, outputPrefix, blob.ID(sessionID), &data2)
 121			if err != nil {
 122				return errors.Wrap(err, "error encrypting")
 123			}
 124	
 125			if err := m.st.PutBlob(ctx, blobID, data2.Bytes(), blob.PutOptions{}); err != nil {
 126				return errors.Wrap(err, "error writing index blob")
 127			}
 128		}
 129	
 130		return nil
 131	}
