 133	// WriteIndexBlobs writes dataShards into new index blobs with an optional blob name suffix.
 134	// The writes are atomic in the sense that if any of them fails, the reader will
 135	// ignore all of the indexes that share the same suffix.
 136	func (m *ManagerV1) WriteIndexBlobs(ctx context.Context, dataShards []gather.Bytes, suffix blob.ID) ([]blob.Metadata, error) {
 137		shards := map[blob.ID]blob.Bytes{}
 138	
 139		suffix = blob.ID(fmt.Sprintf("%v-c%v", suffix, len(dataShards)))
 140	
 141		for _, data := range dataShards {
 142			// important - we're intentionally using data2 in the inner loop scheduling multiple Close()
 143			// we want all Close() to be called at the end of the function after WriteIndex()
 144			data2 := gather.NewWriteBuffer()
 145			defer data2.Close() //nolint:gocritic
 146	
 147			unprefixedBlobID, err := blobcrypto.Encrypt(m.enc.crypter, data, "", suffix, data2)
 148			if err != nil {
 149				return nil, errors.Wrap(err, "error encrypting")
 150			}
 151	
 152			shards[unprefixedBlobID] = data2.Bytes()
 153		}
 154	
 155		//nolint:wrapcheck
 156		return m.epochMgr.WriteIndex(ctx, shards)
 157	}
