 165	func (m *ManagerV1) PrepareUpgradeToIndexBlobManagerV1(ctx context.Context, v0 *ManagerV0) error {
 166		ibl, _, err := v0.ListActiveIndexBlobs(ctx)
 167		if err != nil {
 168			return errors.Wrap(err, "error listing active index blobs")
 169		}
 170	
 171		var blobIDs []blob.ID
 172	
 173		for _, ib := range ibl {
 174			blobIDs = append(blobIDs, ib.BlobID)
 175		}
 176	
 177		if err := m.CompactEpoch(ctx, blobIDs, epoch.UncompactedEpochBlobPrefix(epoch.FirstEpoch)); err != nil {
 178			return errors.Wrap(err, "unable to generate initial epoch")
 179		}
 180	
 181		return nil
 182	}
