 24	// smallIndexEntryCountThreshold is the threshold to determine whether an
 25	// index is small. Any index with fewer entries than this threshold
 26	// will be combined in-memory to reduce the number of segments and speed up
 27	// large index operations (such as verification of all contents).
 28	const smallIndexEntryCountThreshold = 100
 29	
 30	type committedContentIndex struct {
 31		rev   atomic.Int64
 32		cache committedContentIndexCache
 33	
 34		mu sync.RWMutex
 35		// +checklocks:mu
 36		permissiveCacheLoading bool
 37		// +checklocks:mu
 38		deletionWatermark time.Time
 39		// +checklocks:mu
 40		inUse map[blob.ID]index.Index
 41		// +checklocks:mu
 42		merged index.Merged
 43	
 44		v1PerContentOverhead func() int
 45		formatProvider       format.Provider
 46	
 47		// fetchIndexBlob retrieves one index blob from storage
 48		fetchIndexBlob func(ctx context.Context, blobID blob.ID, output *gather.WriteBuffer) error
 49	
 50		log *contentlog.Logger
 51	}
 52	
 53	type committedContentIndexCache interface {
 54		hasIndexBlobID(ctx context.Context, indexBlob blob.ID) (bool, error)
 55		addContentToCache(ctx context.Context, indexBlob blob.ID, data gather.Bytes) error
 56		openIndex(ctx context.Context, indexBlob blob.ID) (index.Index, error)
 57		expireUnused(ctx context.Context, used []blob.ID) error
 58	}
 59	
 60	func (c *committedContentIndex) revision() int64 {
 61		return c.rev.Load()
 62	}
 63	
 64	func (c *committedContentIndex) getContent(contentID ID) (Info, error) {
 65		c.mu.RLock()
 66		defer c.mu.RUnlock()
 67	
 68		var info Info
 69	
 70		ok, err := c.merged.GetInfo(contentID, &info)
 71		if ok {
 72			if shouldIgnore(info, c.deletionWatermark) {
 73				return index.Info{}, ErrContentNotFound
 74			}
 75	
 76			return info, nil
 77		}
 78	
 79		if err == nil {
 80			return index.Info{}, ErrContentNotFound
 81		}
 82	
 83		return index.Info{}, errors.Wrap(err, "error getting content info from index")
 84	}
 85	
 86	func shouldIgnore(id index.Info, deletionWatermark time.Time) bool {
 87		if !id.Deleted {
 88			return false
 89		}
 90	
 91		return !id.Timestamp().After(deletionWatermark)
 92	}
 93	
 94	func (c *committedContentIndex) addIndexBlob(ctx context.Context, indexBlobID blob.ID, data gather.Bytes, use bool) error {
 95		// ensure we bump revision number AFTER this function
 96		// doing it prematurely might confuse callers of revision() who may cache
 97		// a set of old contents and associate it with new revision, before new contents
 98		// are actually available.
 99		defer func() {
100			c.rev.Add(1)
101		}()
102	
103		if err := c.cache.addContentToCache(ctx, indexBlobID, data); err != nil {
104			return errors.Wrap(err, "error adding content to cache")
105		}
106	
107		if !use {
108			return nil
109		}
110	
111		c.mu.Lock()
112		defer c.mu.Unlock()
113	
114		if c.inUse[indexBlobID] != nil {
115			return nil
116		}
117	
118		contentlog.Log1(ctx, c.log, "use-new-committed-index", blobparam.BlobID("indexBlobID", indexBlobID))
119	
120		ndx, err := c.cache.openIndex(ctx, indexBlobID)
121		if err != nil {
122			return errors.Wrapf(err, "unable to open pack index %q", indexBlobID)
123		}
124	
125		c.inUse[indexBlobID] = ndx
126		c.merged = append(c.merged, ndx)
127	
128		return nil
129	}
130	
131	func (c *committedContentIndex) listContents(r IDRange, cb func(i Info) error) error {
132		c.mu.RLock()
133		m := append(index.Merged(nil), c.merged...)
134		deletionWatermark := c.deletionWatermark
135		c.mu.RUnlock()
136	
137		//nolint:wrapcheck
138		return m.Iterate(r, func(i index.Info) error {
139			if shouldIgnore(i, deletionWatermark) {
140				return nil
141			}
142	
143			return cb(i)
144		})
145	}
146	
147	// +checklocks:c.mu
148	func (c *committedContentIndex) indexFilesChanged(indexFiles []blob.ID) bool {
149		if len(indexFiles) != len(c.inUse) {
150			return true
151		}
152	
153		for _, ndx := range indexFiles {
154			if c.inUse[ndx] == nil {
155				return true
156			}
157		}
158	
159		return false
160	}
161	
162	// +checklocks:c.mu
163	func (c *committedContentIndex) merge(ctx context.Context, indexFiles []blob.ID) (index.Merged, map[blob.ID]index.Index, error) {
164		var (
165			newMerged   index.Merged
166			newlyOpened index.Merged // new indexes that were not in c.inUse before
167			newUsedMap  = map[blob.ID]index.Index{}
168		)
169	
170		for _, e := range indexFiles {
171			ndx := c.inUse[e]
172			if ndx == nil {
173				var err error
174	
175				ndx, err = c.cache.openIndex(ctx, e)
176				if err != nil {
177					if c.permissiveCacheLoading {
178						continue
179					}
180	
181					newlyOpened.Close() //nolint:errcheck
182	
183					return nil, nil, errors.Wrapf(err, "unable to open pack index %q", e)
184				}
185	
186				newlyOpened = append(newlyOpened, ndx)
187			}
188	
189			newMerged = append(newMerged, ndx)
190			newUsedMap[e] = ndx
191		}
192	
193		mergedAndCombined, err := c.combineSmallIndexes(ctx, newMerged)
194		if err != nil {
195			newlyOpened.Close() //nolint:errcheck
196	
197			return nil, nil, errors.Wrap(err, "unable to combine small indexes")
198		}
199	
200		contentlog.Log2(ctx, c.log, "combined index segments", logparam.Int("original", len(newMerged)), logparam.Int("merged", len(mergedAndCombined)))
201	
202		return mergedAndCombined, newUsedMap, nil
203	}
204	
205	// Uses indexFiles for indexing. An error is returned if the
206	// indices cannot be read for any reason.
207	func (c *committedContentIndex) use(ctx context.Context, indexFiles []blob.ID, ignoreDeletedBefore time.Time) error {
208		c.mu.Lock()
209		defer c.mu.Unlock()
210	
211		c.deletionWatermark = ignoreDeletedBefore
212	
213		if !c.indexFilesChanged(indexFiles) {
214			return nil
215		}
216	
217		contentlog.Log1(ctx, c.log, "use-indexes",
218			blobparam.BlobIDList("indexFiles", indexFiles))
219	
220		mergedAndCombined, newInUse, err := c.merge(ctx, indexFiles)
221		if err != nil {
222			return err
223		}
224	
225		c.rev.Add(1)
226		c.merged = mergedAndCombined
227	
228		oldInUse := c.inUse
229		c.inUse = newInUse
230	
231		// close indices that were previously in use but are no longer.
232		for k, old := range oldInUse {
233			if newInUse[k] == nil {
234				if err := old.Close(); err != nil {
235					contentlog.Log1(ctx, c.log,
236						"unable to close unused index file",
237						logparam.Error("err", err))
238				}
239			}
240		}
241	
242		if err := c.cache.expireUnused(ctx, indexFiles); err != nil {
243			contentlog.Log1(ctx, c.log,
244				"unable to expire unused index files",
245				logparam.Error("err", err))
246		}
247	
248		return nil
249	}
250	
251	func (c *committedContentIndex) combineSmallIndexes(ctx context.Context, m index.Merged) (index.Merged, error) {
252		var toKeep, toMerge index.Merged
253	
254		for _, ndx := range m {
255			if ndx.ApproximateCount() < smallIndexEntryCountThreshold {
256				toMerge = append(toMerge, ndx)
257			} else {
258				toKeep = append(toKeep, ndx)
259			}
260		}
261	
262		if len(toMerge) <= 1 {
263			return m, nil
264		}
265	
266		b := index.Builder{}
267	
268		for _, ndx := range toMerge {
269			if err := ndx.Iterate(index.AllIDs, func(i index.Info) error {
270				b.Add(i)
271				return nil
272			}); err != nil {
273				return nil, errors.Wrap(err, "unable to iterate index entries")
274			}
275		}
276	
277		mp, mperr := c.formatProvider.GetMutableParameters(ctx)
278		if mperr != nil {
279			return nil, errors.Wrap(mperr, "error getting mutable parameters")
280		}
281	
282		var buf bytes.Buffer
283	
284		if err := b.Build(&buf, mp.IndexVersion); err != nil {
285			return nil, errors.Wrap(err, "error building combined in-memory index")
286		}
287	
288		combined, err := index.Open(buf.Bytes(), nil, c.v1PerContentOverhead)
289		if err != nil {
290			return nil, errors.Wrap(err, "error opening combined in-memory index")
291		}
292	
293		return append(toKeep, combined), nil
294	}
295	
296	func (c *committedContentIndex) close() error {
297		c.mu.Lock()
298		defer c.mu.Unlock()
299	
300		for _, pi := range c.inUse {
301			if err := pi.Close(); err != nil {
302				return errors.Wrap(err, "unable to close index")
303			}
304		}
305	
306		return nil
307	}
308	
309	func (c *committedContentIndex) fetchIndexBlobs(ctx context.Context, isPermissiveCacheLoading bool, indexBlobs []blob.ID) error {
310		ch, err := c.missingIndexBlobs(ctx, indexBlobs)
311		if err != nil {
312			return err
313		}
314	
315		if len(ch) == 0 {
316			return nil
317		}
318	
319		contentlog.Log1(ctx, c.log, "Downloading new index blobs", logparam.Int("len", len(indexBlobs)))
320	
321		eg, ctx := errgroup.WithContext(ctx)
322	
323		for range parallelFetches {
324			eg.Go(func() error {
325				var data gather.WriteBuffer
326				defer data.Close()
327	
328				for indexBlobID := range ch {
329					data.Reset()
330	
331					if err := c.fetchIndexBlob(ctx, indexBlobID, &data); err != nil {
332						if isPermissiveCacheLoading {
333							contentlog.Log1(ctx, c.log, "skipping bad read of index blob", blobparam.BlobID("indexBlobID", indexBlobID))
334							continue
335						}
336	
337						return errors.Wrapf(err, "error loading index blob %v", indexBlobID)
338					}
339	
340					if err := c.addIndexBlob(ctx, indexBlobID, data.Bytes(), false); err != nil {
341						return errors.Wrap(err, "unable to add to committed content cache")
342					}
343				}
344	
345				return nil
346			})
347		}
348	
349		if err := eg.Wait(); err != nil {
350			return errors.Wrap(err, "error downloading indexes")
351		}
352	
353		contentlog.Log(ctx, c.log, "Index blobs downloaded")
354	
355		return nil
356	}
357	
358	// missingIndexBlobs returns a closed channel filled with blob IDs that are not in committedContents cache.
359	func (c *committedContentIndex) missingIndexBlobs(ctx context.Context, blobs []blob.ID) (<-chan blob.ID, error) {
360		ch := make(chan blob.ID, len(blobs))
361		defer close(ch)
362	
363		for _, id := range blobs {
364			has, err := c.cache.hasIndexBlobID(ctx, id)
365			if err != nil {
366				return nil, errors.Wrapf(err, "error determining whether index blob %v has been downloaded", id)
367			}
368	
369			if !has {
370				ch <- id
371			}
372		}
373	
374		return ch, nil
375	}
376	
377	func newCommittedContentIndex(caching *CachingOptions,
378		v1PerContentOverhead func() int,
379		formatProvider format.Provider,
380		permissiveCacheLoading bool,
381		fetchIndexBlob func(ctx context.Context, blobID blob.ID, output *gather.WriteBuffer) error,
382		log *contentlog.Logger,
383		minSweepAge time.Duration,
384	) *committedContentIndex {
385		var cache committedContentIndexCache
386	
387		if caching.CacheDirectory != "" {
388			dirname := filepath.Join(caching.CacheDirectory, "indexes")
389			cache = &diskCommittedContentIndexCache{dirname, clock.Now, v1PerContentOverhead, log, minSweepAge}
390		} else {
391			cache = &memoryCommittedContentIndexCache{
392				contents:             map[blob.ID]index.Index{},
393				v1PerContentOverhead: v1PerContentOverhead,
394			}
395		}
396	
397		return &committedContentIndex{
398			cache:                  cache,
399			permissiveCacheLoading: permissiveCacheLoading,
400			inUse:                  map[blob.ID]index.Index{},
401			v1PerContentOverhead:   v1PerContentOverhead,
402			formatProvider:         formatProvider,
403			fetchIndexBlob:         fetchIndexBlob,
404			log:                    log,
405		}
406	}
407	package index
408	
409	import (
410		"container/heap"
411		stderrors "errors"
412		"sync"
413	
414		"github.com/pkg/errors"
415	)
416	
417	// Merged is an implementation of Index that transparently merges returns from underlying Indexes.
418	type Merged []Index
419	
420	// ApproximateCount implements Index interface.
421	func (m Merged) ApproximateCount() int {
422		c := 0
423	
424		for _, ndx := range m {
425			c += ndx.ApproximateCount()
426		}
427	
428		return c
429	}
430	
431	// Close closes all underlying indexes.
432	func (m Merged) Close() error {
433		var err error
434	
435		for _, ndx := range m {
436			err = stderrors.Join(err, ndx.Close())
437		}
438	
439		return errors.Wrap(err, "closing index shards")
440	}
441	
442	func contentInfoGreaterThanStruct(a, b *Info) bool {
443		if l, r := a.TimestampSeconds, b.TimestampSeconds; l != r {
444			// different timestamps, higher one wins
445			return l > r
446		}
447	
448		if l, r := a.Deleted, b.Deleted; l != r {
449			// non-deleted is greater than deleted.
450			return !a.Deleted
451		}
452	
453		// both same time, both deleted, we must ensure we always resolve to the same pack blob.
454		// since pack blobs are random and unique, simple lexicographic ordering will suffice.
455		return a.PackBlobID > b.PackBlobID
456	}
457	
458	// GetInfo returns information about a single content. If a content is not found, returns (false,nil).
459	func (m Merged) GetInfo(id ID, result *Info) (bool, error) {
460		var (
461			found bool
462			tmp   Info
463		)
464	
465		for _, ndx := range m {
466			ok, err := ndx.GetInfo(id, &tmp)
467			if err != nil {
468				return false, errors.Wrapf(err, "error getting id %v from index shard", id)
469			}
470	
471			if !ok {
472				continue
473			}
474	
475			if !found || contentInfoGreaterThanStruct(&tmp, result) {
476				*result = tmp
477				found = true
478			}
479		}
480	
481		return found, nil
482	}
483	
484	type nextInfo struct {
485		it Info
486		ch <-chan Info
487	}
488	
489	//nolint:recvcheck
490	type nextInfoHeap []*nextInfo
491	
492	func (h nextInfoHeap) Len() int { return len(h) }
493	func (h nextInfoHeap) Less(i, j int) bool {
494		if a, b := h[i].it.ContentID, h[j].it.ContentID; a != b {
495			return a.less(b)
496		}
497	
498		return !contentInfoGreaterThanStruct(&h[i].it, &h[j].it)
499	}
500	
501	func (h nextInfoHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
502	func (h *nextInfoHeap) Push(x any) {
503		*h = append(*h, x.(*nextInfo)) //nolint:forcetypeassert
504	}
505	
506	func (h *nextInfoHeap) Pop() any {
507		old := *h
508		n := len(old)
509		x := old[n-1]
510		*h = old[0 : n-1]
511	
512		return x
513	}
514	
515	func iterateChan(r IDRange, ndx Index, done chan bool, wg *sync.WaitGroup) <-chan Info {
516		ch := make(chan Info, 1)
517	
518		go func() {
519			defer wg.Done()
520			defer close(ch)
521	
522			_ = ndx.Iterate(r, func(i Info) error {
523				select {
524				case <-done:
525					return errors.New("end of iteration")
526				case ch <- i:
527					return nil
528				}
529			})
530		}()
531	
532		return ch
533	}
534	
535	// Iterate invokes the provided callback for all unique content IDs in the underlying sources until either
536	// all contents have been visited or until an error is returned by the callback.
537	func (m Merged) Iterate(r IDRange, cb func(i Info) error) error {
538		var minHeap nextInfoHeap
539	
540		done := make(chan bool)
541	
542		wg := &sync.WaitGroup{}
543	
544		for _, ndx := range m {
545			wg.Add(1)
546	
547			ch := iterateChan(r, ndx, done, wg)
548	
549			it, ok := <-ch
550			if ok {
551				heap.Push(&minHeap, &nextInfo{it, ch})
552			}
553		}
554	
555		// make sure all iterateChan() complete before we return, otherwise they may be trying to reference
556		// index structures that have been closed.
557		defer wg.Wait()
558		defer close(done)
559	
560		var (
561			havePendingItem bool
562			pendingItem     Info
563		)
564	
565		for len(minHeap) > 0 {
566			//nolint:forcetypeassert
567			minNextInfo := heap.Pop(&minHeap).(*nextInfo)
568			if !havePendingItem || pendingItem.ContentID != minNextInfo.it.ContentID {
569				if havePendingItem {
570					if err := cb(pendingItem); err != nil {
571						return err
572					}
573				}
574	
575				pendingItem = minNextInfo.it
576				havePendingItem = true
577			} else if contentInfoGreaterThanStruct(&minNextInfo.it, &pendingItem) {
578				pendingItem = minNextInfo.it
579			}
580	
581			it, ok := <-minNextInfo.ch
582			if ok {
583				heap.Push(&minHeap, &nextInfo{it, minNextInfo.ch})
584			}
585		}
586	
587		if havePendingItem {
588			return cb(pendingItem)
589		}
590	
591		return nil
592	}
593	
594	var _ Index = (*Merged)(nil)
