612	
613	// Refresh reloads the committed content indexes.
614	func (sm *SharedManager) Refresh(ctx context.Context) error {
615		sm.indexesLock.Lock()
616		defer sm.indexesLock.Unlock()
617	
618		timer := timetrack.StartTimer()
619	
620		ibm, err := sm.indexBlobManager(ctx)
621		if err != nil {
622			return err
623		}
624	
625		ibm.Invalidate()
626	
627		err = sm.loadPackIndexesLocked(ctx)
628	
629		contentlog.Log2(ctx, sm.log, "refreshIndexes",
630			logparam.Duration("latency", timer.Elapsed()),
631			logparam.Error("error", err))
632	
633		return err
634	}
635	
636	// CompactIndexes performs compaction of index blobs ensuring that # of small index blobs is below opt.maxSmallBlobs.
637	func (sm *SharedManager) CompactIndexes(ctx context.Context, opt indexblob.CompactOptions) (*maintenancestats.CompactIndexesStats, error) {
638		// we must hold the lock here to avoid the race with Refresh() which can reload the
639		// current set of indexes while we process them.
640		sm.indexesLock.Lock()
641		defer sm.indexesLock.Unlock()
642	
643		contentlog.Log4(ctx, sm.log, "CompactIndexes",
644			logparam.Bool("allIndexes", opt.AllIndexes),
645			logparam.Int64("maxSmallBlobs", int64(opt.MaxSmallBlobs)),
646			logparam.Time("dropDeletedBefore", opt.DropDeletedBefore),
647			logparam.Bool("disableEventualConsistencySafety", opt.DisableEventualConsistencySafety))
648	
649		ibm, err := sm.indexBlobManager(ctx)
650		if err != nil {
651			return nil, err
652		}
653	
654		stats, err := ibm.Compact(ctx, opt)
655		if err != nil {
656			return nil, errors.Wrap(err, "error performing compaction")
657		}
658	
659		// reload indexes after compaction.
660		if err := sm.loadPackIndexesLocked(ctx); err != nil {
661			return nil, errors.Wrap(err, "error re-loading indexes")
662		}
663	
664		return stats, nil
665	}
666	
667	// ParseIndexBlob loads entries in a given index blob and returns them.
668	func ParseIndexBlob(blobID blob.ID, encrypted gather.Bytes, crypter blobcrypto.Crypter) ([]Info, error) {
669		var data gather.WriteBuffer
670		defer data.Close()
671	
672		if err := blobcrypto.Decrypt(crypter, encrypted, blobID, &data); err != nil {
673			return nil, errors.Wrap(err, "unable to decrypt index blob")
674		}
675	
676		ndx, err := index.Open(data.Bytes().ToByteSlice(), nil, crypter.Encryptor().Overhead)
677		if err != nil {
678			return nil, errors.Wrapf(err, "unable to open index blob")
679		}
680	
681		var results []Info
682	
683		err = ndx.Iterate(index.AllIDs, func(i index.Info) error {
684			results = append(results, i)
685			return nil
686		})
687	
688		return results, errors.Wrap(err, "error iterating index entries")
689	}

