205	// Uses indexFiles for indexing. An error is returned if the
206	// indices cannot be read for any reason.
207	func (c *committedContentIndex) use(ctx context.Context, indexFiles []blob.ID, ignoreDeletedBefore time.Time) error {
208		c.mu.Lock()
209		defer c.mu.Unlock()
210	
211		c.deletionWatermark = ignoreDeletedBefore
212	
213		if !c.indexFilesChanged(indexFiles) {
214			return nil
215		}
216	
217		contentlog.Log1(ctx, c.log, "use-indexes",
218			blobparam.BlobIDList("indexFiles", indexFiles))
219	
220		mergedAndCombined, newInUse, err := c.merge(ctx, indexFiles)
221		if err != nil {
222			return err
223		}
224	
225		c.rev.Add(1)
226		c.merged = mergedAndCombined
227	
228		oldInUse := c.inUse
229		c.inUse = newInUse
230	
231		// close indices that were previously in use but are no longer.
232		for k, old := range oldInUse {
233			if newInUse[k] == nil {
234				if err := old.Close(); err != nil {
235					contentlog.Log1(ctx, c.log,
236						"unable to close unused index file",
237						logparam.Error("err", err))
238				}
239			}
240		}
241	
242		if err := c.cache.expireUnused(ctx, indexFiles); err != nil {
243			contentlog.Log1(ctx, c.log,
244				"unable to expire unused index files",
245				logparam.Error("err", err))
246		}
247	
248		return nil
249	}
