251	func (c *committedContentIndex) combineSmallIndexes(ctx context.Context, m index.Merged) (index.Merged, error) {
252		var toKeep, toMerge index.Merged
253	
254		for _, ndx := range m {
255			if ndx.ApproximateCount() < smallIndexEntryCountThreshold {
256				toMerge = append(toMerge, ndx)
257			} else {
258				toKeep = append(toKeep, ndx)
259			}
260		}
261	
262		if len(toMerge) <= 1 {
263			return m, nil
264		}
265	
266		b := index.Builder{}
267	
268		for _, ndx := range toMerge {
269			if err := ndx.Iterate(index.AllIDs, func(i index.Info) error {
270				b.Add(i)
271				return nil
272			}); err != nil {
273				return nil, errors.Wrap(err, "unable to iterate index entries")
274			}
275		}
276	
277		mp, mperr := c.formatProvider.GetMutableParameters(ctx)
278		if mperr != nil {
279			return nil, errors.Wrap(mperr, "error getting mutable parameters")
280		}
281	
282		var buf bytes.Buffer
283	
284		if err := b.Build(&buf, mp.IndexVersion); err != nil {
285			return nil, errors.Wrap(err, "error building combined in-memory index")
286		}
287	
288		combined, err := index.Open(buf.Bytes(), nil, c.v1PerContentOverhead)
289		if err != nil {
290			return nil, errors.Wrap(err, "error opening combined in-memory index")
291		}
292	
293		return append(toKeep, combined), nil
294	}
