416	
417	// Merged is an implementation of Index that transparently merges returns from underlying Indexes.
418	type Merged []Index
419	
420	// ApproximateCount implements Index interface.
421	func (m Merged) ApproximateCount() int {
422		c := 0
423	
424		for _, ndx := range m {
425			c += ndx.ApproximateCount()
426		}
427	
428		return c
429	}
430	
431	// Close closes all underlying indexes.
432	func (m Merged) Close() error {
433		var err error
434	
435		for _, ndx := range m {
436			err = stderrors.Join(err, ndx.Close())
437		}
438	
439		return errors.Wrap(err, "closing index shards")
440	}
441	
442	func contentInfoGreaterThanStruct(a, b *Info) bool {
443		if l, r := a.TimestampSeconds, b.TimestampSeconds; l != r {
444			// different timestamps, higher one wins
445			return l > r
446		}
447	
448		if l, r := a.Deleted, b.Deleted; l != r {
449			// non-deleted is greater than deleted.
450			return !a.Deleted
451		}
452	
453		// both same time, both deleted, we must ensure we always resolve to the same pack blob.
454		// since pack blobs are random and unique, simple lexicographic ordering will suffice.
455		return a.PackBlobID > b.PackBlobID
456	}
457	
458	// GetInfo returns information about a single content. If a content is not found, returns (false,nil).
459	func (m Merged) GetInfo(id ID, result *Info) (bool, error) {
460		var (
461			found bool
462			tmp   Info
463		)
464	
465		for _, ndx := range m {
466			ok, err := ndx.GetInfo(id, &tmp)
467			if err != nil {
468				return false, errors.Wrapf(err, "error getting id %v from index shard", id)
469			}
470	
471			if !ok {
472				continue
473			}
474	
475			if !found || contentInfoGreaterThanStruct(&tmp, result) {
476				*result = tmp
477				found = true
478			}
479		}
480	
481		return found, nil
482	}
483	
484	type nextInfo struct {
485		it Info
486		ch <-chan Info
487	}
488	
489	//nolint:recvcheck
490	type nextInfoHeap []*nextInfo
491	
492	func (h nextInfoHeap) Len() int { return len(h) }
493	func (h nextInfoHeap) Less(i, j int) bool {
494		if a, b := h[i].it.ContentID, h[j].it.ContentID; a != b {
495			return a.less(b)
496		}
497	
498		return !contentInfoGreaterThanStruct(&h[i].it, &h[j].it)
499	}
500	
501	func (h nextInfoHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
502	func (h *nextInfoHeap) Push(x any) {
503		*h = append(*h, x.(*nextInfo)) //nolint:forcetypeassert
504	}
505	
506	func (h *nextInfoHeap) Pop() any {
507		old := *h
508		n := len(old)
509		x := old[n-1]
510		*h = old[0 : n-1]
511	
512		return x
513	}
514	
515	func iterateChan(r IDRange, ndx Index, done chan bool, wg *sync.WaitGroup) <-chan Info {
516		ch := make(chan Info, 1)
517	
518		go func() {
519			defer wg.Done()
520			defer close(ch)
521	
522			_ = ndx.Iterate(r, func(i Info) error {
523				select {
524				case <-done:
525					return errors.New("end of iteration")
526				case ch <- i:
527					return nil
528				}
529			})
530		}()
531	
532		return ch
533	}
534	
535	// Iterate invokes the provided callback for all unique content IDs in the underlying sources until either
536	// all contents have been visited or until an error is returned by the callback.
537	func (m Merged) Iterate(r IDRange, cb func(i Info) error) error {
538		var minHeap nextInfoHeap
539	
540		done := make(chan bool)
541	
542		wg := &sync.WaitGroup{}
543	
544		for _, ndx := range m {
545			wg.Add(1)
546	
547			ch := iterateChan(r, ndx, done, wg)
548	
549			it, ok := <-ch
550			if ok {
551				heap.Push(&minHeap, &nextInfo{it, ch})
552			}
553		}
554	
555		// make sure all iterateChan() complete before we return, otherwise they may be trying to reference
556		// index structures that have been closed.
557		defer wg.Wait()
558		defer close(done)
559	
560		var (
561			havePendingItem bool
562			pendingItem     Info
563		)
564	
565		for len(minHeap) > 0 {
566			//nolint:forcetypeassert
567			minNextInfo := heap.Pop(&minHeap).(*nextInfo)
568			if !havePendingItem || pendingItem.ContentID != minNextInfo.it.ContentID {
569				if havePendingItem {
570					if err := cb(pendingItem); err != nil {
571						return err
572					}
573				}
574	
575				pendingItem = minNextInfo.it
576				havePendingItem = true
577			} else if contentInfoGreaterThanStruct(&minNextInfo.it, &pendingItem) {
578				pendingItem = minNextInfo.it
579			}
580	
581			it, ok := <-minNextInfo.ch
582			if ok {
583				heap.Push(&minHeap, &nextInfo{it, minNextInfo.ch})
584			}
585		}
586	
587		if havePendingItem {
588			return cb(pendingItem)
589		}
590	
591		return nil
592	}
593	
594	var _ Index = (*Merged)(nil)
