 33	func maybeParallelExecutor(parallel int, originalCallback IterateCallback) (IterateCallback, cancelIterateFunc) {
 34		if parallel <= 1 {
 35			return originalCallback, func() error { return nil }
 36		}
 37	
 38		workch := make(chan Info, parallel)
 39		workererrch := make(chan error, 1)
 40	
 41		var wg sync.WaitGroup
 42	
 43		var once sync.Once
 44	
 45		lastWorkerError := func() error {
 46			select {
 47			case err := <-workererrch:
 48				return err
 49			default:
 50				return nil
 51			}
 52		}
 53	
 54		cleanup := func() error {
 55			once.Do(func() {
 56				close(workch)
 57				wg.Wait()
 58			})
 59	
 60			return lastWorkerError()
 61		}
 62	
 63		callback := func(i Info) error {
 64			workch <- i
 65			return lastWorkerError()
 66		}
 67	
 68		// start N workers, each fetching from the shared channel and invoking the provided callback.
 69		// cleanup() must be called to for worker completion
 70		for range parallel {
 71			wg.Go(func() {
 72				for i := range workch {
 73					if err := originalCallback(i); err != nil {
 74						select {
 75						case workererrch <- err:
 76						default:
 77						}
 78					}
 79				}
 80			})
 81		}
 82	
 83		return callback, cleanup
 84	}
