121			if !opts.IncludeDeleted {
122				if ci, ok := uncommitted[i.ContentID]; ok {
123					if ci.Deleted {
124						return nil
125					}
126				} else if i.Deleted {
127					return nil
128				}
129			}
130	
131			if !opts.Range.Contains(i.ContentID) {
132				return nil
133			}
134	
135			return callback(i)
136		}
