147		if err := bm.maybeRefreshIndexes(ctx); err != nil {
148			return err
149		}
150	
151		if err := bm.committedContents.listContents(opts.Range, invokeCallback); err != nil {
152			return err
153		}
154	
155		return cleanup()
156	}
