187	// IteratePacksCallback is the function type used as callback during pack iteration.
188	type IteratePacksCallback func(PackInfo) error
189	
190	// IteratePacks invokes the provided callback for all pack blobs.
191	func (bm *WriteManager) IteratePacks(ctx context.Context, options IteratePackOptions, callback IteratePacksCallback) error {
192		packUsage := map[blob.ID]*PackInfo{}
193	
194		if err := bm.IterateContents(
195			ctx,
196			IterateOptions{
197				IncludeDeleted: options.IncludePacksWithOnlyDeletedContent,
198			},
199			func(ci Info) error {
200				if !options.matchesBlob(ci.PackBlobID) {
201					return nil
202				}
203	
204				pi := packUsage[ci.PackBlobID]
205				if pi == nil {
206					pi = &PackInfo{PackID: ci.PackBlobID}
207					packUsage[ci.PackBlobID] = pi
208				}
209	
210				pi.ContentCount++
211	
212				pi.TotalSize += int64(ci.PackedLength)
213				if options.IncludeContentInfos {
214					pi.ContentInfos = append(pi.ContentInfos, ci)
215				}
216	
217				return nil
218			},
219		); err != nil {
220			return errors.Wrap(err, "error iterating contents")
221		}
222	
223		for _, v := range packUsage {
224			if err := callback(*v); err != nil {
225				return err
226			}
227		}
228	
229		return nil
230	}
