232	// IterateUnreferencedPacks returns the list of unreferenced storage blobs.
233	func (bm *WriteManager) IterateUnreferencedPacks(ctx context.Context, blobPrefixes []blob.ID, parallelism int, callback func(blob.Metadata) error) error {
234		usedPacks, err := bigmap.NewSet(ctx)
235		if err != nil {
236			return errors.Wrap(err, "new set")
237		}
238	
239		defer usedPacks.Close(ctx)
240	
241		contentlog.Log(ctx, bm.log, "determining blobs in use")
242		// find packs in use
243		if err := bm.IteratePacks(
244			ctx,
245			IteratePackOptions{
246				Prefixes:                           blobPrefixes,
247				IncludePacksWithOnlyDeletedContent: true,
248			},
249			func(pi PackInfo) error {
250				if pi.ContentCount > 0 {
251					usedPacks.Put(ctx, []byte(pi.PackID))
252				}
253	
254				return nil
255			},
256		); err != nil {
257			return errors.Wrap(err, "error iterating packs")
258		}
259	
260		if len(blobPrefixes) == 0 {
261			blobPrefixes = PackBlobIDPrefixes
262		}
263	
264		var prefixes []blob.ID
265	
266		if parallelism <= len(blobPrefixes) {
267			prefixes = append(prefixes, blobPrefixes...)
268		} else {
269			// iterate {p,q}[0-9,a-f]
270			for _, prefix := range blobPrefixes {
271				for hexDigit := range 16 {
272					prefixes = append(prefixes, blob.ID(fmt.Sprintf("%v%x", prefix, hexDigit)))
273				}
274			}
275		}
276	
277		contentlog.Log1(ctx, bm.log, "scanning prefixes",
278			blobparam.BlobIDList("prefixes", prefixes))
279	
280		var unusedCount atomic.Int32
281	
282		if err := blob.IterateAllPrefixesInParallel(ctx, parallelism, bm.st, prefixes,
283			func(bm blob.Metadata) error {
284				if usedPacks.Contains([]byte(bm.BlobID)) {
285					return nil
286				}
287	
288				unusedCount.Add(1)
289	
290				return callback(bm)
291			}); err != nil {
292			return errors.Wrap(err, "error iterating blobs")
293		}
294	
295		contentlog.Log1(ctx, bm.log, "found pack blobs not in use", logparam.Int("unusedCount", int(unusedCount.Load())))
296	
297		return nil
298	}

