 635	func (e *Manager) loadUncompactedEpochs(ctx context.Context, first, last int) (map[int][]blob.Metadata, error) {
 636		var mu sync.Mutex
 637	
 638		result := map[int][]blob.Metadata{}
 639	
 640		eg, ctx := errgroup.WithContext(ctx)
 641	
 642		for n := first; n <= last; n++ {
 643			if n < 0 {
 644				continue
 645			}
 646	
 647			eg.Go(func() error {
 648				bm, err := blob.ListAllBlobs(ctx, e.st, UncompactedEpochBlobPrefix(n))
 649				if err != nil {
 650					return errors.Wrapf(err, "error listing uncompacted epoch %v", n)
 651				}
 652	
 653				mu.Lock()
 654				defer mu.Unlock()
 655	
 656				result[n] = bm
 657	
 658				return nil
 659			})
 660		}
 661	
 662		if err := eg.Wait(); err != nil {
