 797	// GetCompleteIndexSet returns the set of blobs forming a complete index set up to the provided epoch number.
 798	func (e *Manager) GetCompleteIndexSet(ctx context.Context, maxEpoch int) ([]blob.Metadata, time.Time, error) {
 799		for {
 800			cs, err := e.committedState(ctx, 0)
 801			if err != nil {
 802				return nil, time.Time{}, err
 803			}
 804	
 805			if maxEpoch == LatestEpoch {
 806				maxEpoch = cs.WriteEpoch + 1
 807			}
 808	
 809			result, err := e.getCompleteIndexSetForCommittedState(ctx, cs, 0, maxEpoch)
 810			if e.timeFunc().Before(cs.ValidUntil) {
 811				contentlog.Log4(
 812					ctx, e.log,
 813					"complete index set",
 814					logparam.Int("maxEpoch", maxEpoch),
 815					logparam.Int("resultLength", len(result)),
 816					blobparam.BlobIDList("result", blob.IDsFromMetadata(result)),
 817					logparam.Time("deletionWatermark", cs.DeletionWatermark),
 818				)
 819	
 820				return result, cs.DeletionWatermark, err
 821			}
 822	
 823			// We need to retry if local process took too long (e.g. because the machine went
 824			// to sleep at the wrong moment) and committed state is no longer valid.
 825			//
 826			// One scenario where this matters is cleanup: if determining the set of indexes takes
 827			// too long, it's possible for a cleanup process to delete some of the uncompacted
 828			// indexes that are still treated as authoritative according to old committed state.
 829			//
 830			// Retrying will re-examine the state of the world and re-do the logic.
 831			contentlog.Log(ctx, e.log, "GetCompleteIndexSet took too long, retrying to ensure correctness")
 832			atomic.AddInt32(e.getCompleteIndexSetTooSlow, 1)
 833		}
 834	}
