 913	func (e *Manager) deletePartiallyWrittenShards(ctx context.Context, blobs map[blob.ID]blob.Metadata) error {
 914		for blobID := range blobs {
 915			if err := e.st.DeleteBlob(ctx, blobID); err != nil {
 916				return errors.Wrap(err, "error deleting partially written shard")
 917			}
 918		}
 919	
 920		return nil
