1096	func (e *Manager) getIndexesFromEpochInternal(ctx context.Context, cs CurrentSnapshot, epoch int) ([]blob.Metadata, error) {
1097		// check if the epoch is old enough to possibly have compacted blobs
1098		epochSettled := cs.isSettledEpochNumber(epoch)
1099		if epochSettled && cs.SingleEpochCompactionSets[epoch] != nil {
1100			return cs.SingleEpochCompactionSets[epoch], nil
1101		}
1102	
1103		// load uncompacted blobs for this epoch, reusing UncompactedEpochSets if we have it.
1104		uncompactedBlobs, ok := cs.UncompactedEpochSets[epoch]
1105		if !ok {
1106			ue, err := blob.ListAllBlobs(ctx, e.st, UncompactedEpochBlobPrefix(epoch))
1107			if err != nil {
1108				return nil, errors.Wrapf(err, "error listing uncompacted indexes for epoch %v", epoch)
1109			}
1110	
1111			uncompactedBlobs = ue
1112		}
1113	
1114		// return uncompacted blobs to the caller while we're compacting them in background
1115		return uncompactedBlobs, nil
1116	}
