 669	// refreshAttemptLocked attempts to load the committedState of
 670	// the index and updates `lastKnownState` state atomically when complete.
 671	func (e *Manager) refreshAttemptLocked(ctx context.Context) error {
 672		ctx = contentlog.WithParams(ctx,
 673			logparam.String("span:emr", contentlog.RandomSpanID()))
 674	
 675		contentlog.Log(ctx, e.log, "refreshAttempt started")
 676		defer contentlog.Log(ctx, e.log, "refreshAttempt finished")
 677	
 678		p, perr := e.getParameters(ctx)
 679		if perr != nil {
 680			return perr
 681		}
 682	
 683		cs := CurrentSnapshot{
 684			WriteEpoch:                0,
 685			EpochStartTime:            map[int]time.Time{},
 686			UncompactedEpochSets:      map[int][]blob.Metadata{},
 687			SingleEpochCompactionSets: map[int][]blob.Metadata{},
 688			ValidUntil:                e.timeFunc().Add(p.EpochRefreshFrequency),
 689		}
 690	
 691		eg, ctx1 := errgroup.WithContext(ctx)
 692	
 693		eg.Go(func() error {
 694			return e.loadWriteEpoch(ctx1, &cs)
 695		})
 696		eg.Go(func() error {
 697			return e.loadDeletionWatermark(ctx1, &cs)
 698		})
 699		eg.Go(func() error {
 700			return e.loadSingleEpochCompactions(ctx1, &cs)
 701		})
 702		eg.Go(func() error {
 703			return e.loadRangeCheckpoints(ctx1, &cs)
 704		})
 705	
 706		if err := eg.Wait(); err != nil {
 707			return errors.Wrap(err, "error refreshing")
 708		}
 709	
 710		ues, err := e.loadUncompactedEpochs(ctx, cs.WriteEpoch-1, cs.WriteEpoch+1)
 711		if err != nil {
 712			return errors.Wrap(err, "error loading uncompacted epochs")
 713		}
 714	
 715		cs.UncompactedEpochSets = ues
 716	
 717		contentlog.Log5(
 718			ctx, e.log,
 719			"epochs determined",
 720			logparam.Int("writeEpoch", cs.WriteEpoch),
 721			logparam.Int("ues1", len(ues[cs.WriteEpoch-1])),
 722			logparam.Int("ues2", len(ues[cs.WriteEpoch])),
 723			logparam.Int("ues3", len(ues[cs.WriteEpoch+1])),
 724			logparam.Time("validUntil", cs.ValidUntil),
 725		)
 726	
 727		if now := e.timeFunc(); now.After(cs.ValidUntil) {
 728			atomic.AddInt32(e.committedStateRefreshTooSlow, 1)
 729	
 730			return errors.Errorf("refreshing committed state took too long (now %v, valid until %v)", now, cs.ValidUntil.Format(time.RFC3339Nano))
 731		}
 732	
 733		e.lastKnownState = cs
 734	
 735		return nil
 736	}
