 738	// MaybeAdvanceWriteEpoch writes a new write epoch marker when a new write
 739	// epoch should be started, otherwise it does not do anything.
 740	func (e *Manager) MaybeAdvanceWriteEpoch(ctx context.Context) (*maintenancestats.AdvanceEpochStats, error) {
 741		p, err := e.getParameters(ctx)
 742		if err != nil {
 743			return nil, err
 744		}
 745	
 746		cs, err := e.committedState(ctx, 0)
 747		if err != nil {
 748			return nil, err
 749		}
 750	
 751		result := &maintenancestats.AdvanceEpochStats{
 752			CurrentEpoch: maintenancestats.ToUint64(cs.WriteEpoch),
 753		}
 754	
 755		if shouldAdvance(cs.UncompactedEpochSets[cs.WriteEpoch], p.MinEpochDuration, p.EpochAdvanceOnCountThreshold, p.EpochAdvanceOnTotalSizeBytesThreshold) {
 756			if err := e.advanceEpochMarker(ctx, cs); err != nil {
 757				return nil, errors.Wrap(err, "error advancing epoch")
 758			}
 759	
 760			result.CurrentEpoch = maintenancestats.ToUint64(cs.WriteEpoch + 1)
 761			result.WasAdvanced = true
 762		}
 763	
 764		return result, nil
 765	}
