 777	func (e *Manager) committedState(ctx context.Context, ensureMinTime time.Duration) (CurrentSnapshot, error) {
 778		e.mu.Lock()
 779		defer e.mu.Unlock()
 780	
 781		if now := e.timeFunc().Add(ensureMinTime); now.After(e.lastKnownState.ValidUntil) {
 782			contentlog.Log2(
 783				ctx, e.log,
 784				"refreshing committed state because it's no longer valid",
 785				logparam.Time("now", now),
 786				logparam.Time("validUntil", e.lastKnownState.ValidUntil),
 787			)
 788	
 789			if err := e.refreshLocked(ctx); err != nil {
 790				return CurrentSnapshot{}, err
 791			}
 792		}
 793	
 794		return e.lastKnownState, nil
 795	}
 796	
 797	// GetCompleteIndexSet returns the set of blobs forming a complete index set up to the provided epoch number.
 798	func (e *Manager) GetCompleteIndexSet(ctx context.Context, maxEpoch int) ([]blob.Metadata, time.Time, error) {
 799		for {
 800			cs, err := e.committedState(ctx, 0)
 801			if err != nil {
 802				return nil, time.Time{}, err
 803			}
 804	
 805			if maxEpoch == LatestEpoch {
 806				maxEpoch = cs.WriteEpoch + 1
 807			}
 808	
 809			result, err := e.getCompleteIndexSetForCommittedState(ctx, cs, 0, maxEpoch)
 810			if e.timeFunc().Before(cs.ValidUntil) {
 811				contentlog.Log4(
 812					ctx, e.log,
 813					"complete index set",
 814					logparam.Int("maxEpoch", maxEpoch),
 815					logparam.Int("resultLength", len(result)),
 816					blobparam.BlobIDList("result", blob.IDsFromMetadata(result)),
 817					logparam.Time("deletionWatermark", cs.DeletionWatermark),
 818				)
 819	
 820				return result, cs.DeletionWatermark, err
 821			}
 822	
 823			// We need to retry if local process took too long (e.g. because the machine went
 824			// to sleep at the wrong moment) and committed state is no longer valid.
 825			//
 826			// One scenario where this matters is cleanup: if determining the set of indexes takes
 827			// too long, it's possible for a cleanup process to delete some of the uncompacted
 828			// indexes that are still treated as authoritative according to old committed state.
 829			//
 830			// Retrying will re-examine the state of the world and re-do the logic.
 831			contentlog.Log(ctx, e.log, "GetCompleteIndexSet took too long, retrying to ensure correctness")
 832			atomic.AddInt32(e.getCompleteIndexSetTooSlow, 1)
 833		}
 834	}
 835	
 836	var errWriteIndexTryAgain = errors.New("try again")
 837	
 838	// WriteIndex writes new index blob by picking the appropriate prefix based on current epoch.
 839	func (e *Manager) WriteIndex(ctx0 context.Context, dataShards map[blob.ID]blob.Bytes) ([]blob.Metadata, error) {
 840		written := map[blob.ID]blob.Metadata{}
 841		writtenForEpoch := -1
 842	
 843		attempt := 0
 844	
 845		for {
 846			ctx := contentlog.WithParams(ctx0,
 847				logparam.String("span:writeEpochIndex", fmt.Sprintf("attempt-%v", attempt)))
 848	
 849			attempt++
 850	
 851			p, err := e.getParameters(ctx)
 852			if err != nil {
 853				return nil, err
 854			}
 855	
 856			// make sure we have at least 75% of remaining time
 857			//nolint:mnd
 858			cs, err := e.committedState(ctx, 3*p.EpochRefreshFrequency/4)
 859			if err != nil {
 860				return nil, errors.Wrap(err, "error getting committed state")
 861			}
 862	
 863			if cs.WriteEpoch != writtenForEpoch {
 864				if err = e.deletePartiallyWrittenShards(ctx, written); err != nil {
 865					return nil, errors.Wrap(err, "unable to delete partially written shard")
 866				}
 867	
 868				writtenForEpoch = cs.WriteEpoch
 869				written = map[blob.ID]blob.Metadata{}
 870			}
 871	
 872			err = e.writeIndexShards(ctx, dataShards, written, cs)
 873			if errors.Is(err, errWriteIndexTryAgain) {
 874				continue
 875			}
 876	
 877			if err != nil {
 878				contentlog.Log1(ctx, e.log, "index-write-error", logparam.Error("error", err))
 879				return nil, err
 880			}
 881	
 882			e.Invalidate()
 883	
 884			break
 885		}
 886	
 887		cs, err := e.committedState(ctx0, 0)
 888		if err != nil {
 889			return nil, errors.Wrap(err, "error getting committed state")
 890		}
 891	
 892		if cs.WriteEpoch >= writtenForEpoch+2 {
 893			contentlog.Log(ctx0, e.log, "index-write-extremely-slow")
 894	
 895			if err = e.deletePartiallyWrittenShards(ctx0, written); err != nil {
 896				contentlog.Log1(ctx0, e.log, "index-write-extremely-slow-cleanup-failed", logparam.Error("error", err))
 897			}
 898	
 899			return nil, ErrVerySlowIndexWrite
 900		}
 901	
 902		var results []blob.Metadata
 903	
 904		for _, v := range written {
 905			results = append(results, v)
 906		}
 907	
 908		contentlog.Log1(ctx0, e.log, "index-write-success", blobparam.BlobMetadataList("results", results))
 909	
 910		return results, nil
 911	}
 912	
 913	func (e *Manager) deletePartiallyWrittenShards(ctx context.Context, blobs map[blob.ID]blob.Metadata) error {
 914		for blobID := range blobs {
 915			if err := e.st.DeleteBlob(ctx, blobID); err != nil {
 916				return errors.Wrap(err, "error deleting partially written shard")
 917			}
 918		}
 919	
 920		return nil
 921	}
 922	
 923	func (e *Manager) writeIndexShards(ctx context.Context, dataShards map[blob.ID]blob.Bytes, written map[blob.ID]blob.Metadata, cs CurrentSnapshot) error {
 924		contentlog.Log3(ctx, e.log, "writing index shards",
 925			logparam.Int("shardCount", len(dataShards)),
 926			logparam.Time("validUntil", cs.ValidUntil),
 927			logparam.Duration("remaining", cs.ValidUntil.Sub(e.timeFunc())))
 928	
 929		for unprefixedBlobID, data := range dataShards {
 930			blobID := UncompactedEpochBlobPrefix(cs.WriteEpoch) + unprefixedBlobID
 931			if _, ok := written[blobID]; ok {
 932				contentlog.Log1(ctx, e.log,
 933					"already written",
 934					blobparam.BlobID("blobID", blobID))
 935	
 936				continue
 937			}
 938	
 939			if now := e.timeFunc(); !now.Before(cs.ValidUntil) {
 940				contentlog.Log1(ctx, e.log, "write was too slow, retrying", logparam.Time("validUntil", cs.ValidUntil))
 941				atomic.AddInt32(e.writeIndexTooSlow, 1)
 942	
 943				return errWriteIndexTryAgain
 944			}
 945	
 946			bm, err := blob.PutBlobAndGetMetadata(ctx, e.st, blobID, data, blob.PutOptions{})
 947			if err != nil {
 948				return errors.Wrap(err, "error writing index blob")
 949			}
 950	
 951			contentlog.Log1(ctx, e.log, "wrote-index-shard", blobparam.BlobMetadata("metadata", bm))
 952	
 953			written[bm.BlobID] = bm
 954		}
 955	
 956		return nil
 957	}
 958	
 959	// Invalidate ensures that all cached index information is discarded.
 960	func (e *Manager) Invalidate() {
 961		e.mu.Lock()
 962		defer e.mu.Unlock()
 963	
 964		e.lastKnownState = CurrentSnapshot{}
 965	}
 966	
 967	func (e *Manager) getCompleteIndexSetForCommittedState(ctx context.Context, cs CurrentSnapshot, minEpoch, maxEpoch int) ([]blob.Metadata, error) {
 968		var result []blob.Metadata
 969	
 970		startEpoch := minEpoch
 971	
 972		for _, c := range cs.LongestRangeCheckpointSets {
 973			if c.MaxEpoch > startEpoch {
 974				result = append(result, c.Blobs...)
 975				startEpoch = c.MaxEpoch + 1
 976			}
 977		}
 978	
 979		eg, ctx := errgroup.WithContext(ctx)
 980	
 981		contentlog.Log3(
 982			ctx, e.log, "adding incremental state for epochs",
 983			logparam.Int("startEpoch", startEpoch),
 984			logparam.Int("maxEpoch", maxEpoch),
 985			blobparam.BlobIDList("result", blob.IDsFromMetadata(result)),
 986		)
 987	
 988		cnt := maxEpoch - startEpoch + 1
 989	
 990		tmp := make([][]blob.Metadata, cnt)
 991	
 992		for i := range cnt {
 993			ep := i + startEpoch
 994	
 995			eg.Go(func() error {
 996				s, err := e.getIndexesFromEpochInternal(ctx, cs, ep)
 997				if err != nil {
 998					return errors.Wrapf(err, "error getting indexes for epoch %v", ep)
 999				}
1000	
1001				tmp[i] = s
1002	
1003				return nil
1004			})
1005		}
1006	
1007		if err := eg.Wait(); err != nil {
1008			return nil, errors.Wrap(err, "error getting indexes")
1009		}
1010	
1011		for _, v := range tmp {
1012			result = append(result, v...)
1013		}
1014	
1015		return result, nil
1016	}
1017	
1018	// MaybeCompactSingleEpoch compacts the oldest epoch that is eligible for
1019	// compaction if there is one.
1020	func (e *Manager) MaybeCompactSingleEpoch(ctx context.Context) (*maintenancestats.CompactSingleEpochStats, error) {
1021		cs, err := e.committedState(ctx, 0)
1022		if err != nil {
1023			return nil, err
1024		}
1025	
1026		uncompacted, err := oldestUncompactedEpoch(cs)
1027		if err != nil {
1028			return nil, err
1029		}
1030	
1031		// Defense in depth: oldestUncompactedEpoch is expected to always return a
1032		// non-negative, not-yet-compacted epoch, but guard against picking one that
1033		// is already covered by another compacted set.
1034		if uncompacted < 0 {
1035			return nil, errors.Errorf("oldestUncompactedEpoch returned invalid epoch %v", uncompacted)
1036		}
1037	
1038		if !cs.isSettledEpochNumber(uncompacted) {
1039			contentlog.Log1(ctx, e.log, "there are no uncompacted epochs eligible for compaction", logparam.Int("oldestUncompactedEpoch", uncompacted))
1040	
1041			return nil, nil
1042		}
1043	
1044		if _, alreadyCompacted := cs.SingleEpochCompactionSets[uncompacted]; alreadyCompacted {
1045			contentlog.Log1(ctx, e.log, "unexpected: selected epoch is already single-compacted, skipping", logparam.Int("epoch", uncompacted))
1046	
1047			return nil, nil
1048		}
1049	
1050		if rangeCompacted := getRangeCompactedRange(cs); !rangeCompacted.isEmpty() && uncompacted <= rangeCompacted.hi {
1051			contentlog.Log3(ctx, e.log, "unexpected: selected epoch is within the range-compacted window, skipping",
1052				logparam.Int("epoch", uncompacted),
1053				logparam.Int("rangeLo", rangeCompacted.lo),
1054				logparam.Int("rangeHi", rangeCompacted.hi))
1055	
1056			return nil, nil
1057		}
1058	
1059		uncompactedBlobs, ok := cs.UncompactedEpochSets[uncompacted]
1060		if !ok {
1061			// blobs for this epoch were not loaded in the current snapshot, get the list of blobs for this epoch
1062			ue, err := blob.ListAllBlobs(ctx, e.st, UncompactedEpochBlobPrefix(uncompacted))
1063			if err != nil {
1064				return nil, errors.Wrapf(err, "error listing uncompacted indexes for epoch %v", uncompacted)
1065			}
1066	
1067			uncompactedBlobs = ue
1068		}
1069	
1070		if len(uncompactedBlobs) == 0 {
1071			// Does not catch cases where some but not all xn blobs in an epoch are missing;
1072			// e.g. a previous compaction and partial deletion of superseded xn blobs.
1073			return nil, nil
1074		}
1075	
1076		var uncompactedSize uint64
1077		for _, b := range uncompactedBlobs {
1078			uncompactedSize += maintenancestats.ToUint64(b.Length)
1079		}
1080	
1081		result := &maintenancestats.CompactSingleEpochStats{
1082			SupersededIndexBlobCount: uint64(len(uncompactedBlobs)),
1083			SupersededIndexTotalSize: uncompactedSize,
1084			Epoch:                    maintenancestats.ToUint64(uncompacted),
1085		}
1086	
1087		contentlog.Log1(ctx, e.log, "starting single-epoch compaction for epoch", result)
1088	
1089		if err := e.compact(ctx, blob.IDsFromMetadata(uncompactedBlobs), compactedEpochBlobPrefix(uncompacted)); err != nil {
1090			return nil, errors.Wrapf(err, "unable to compact blobs for epoch %v: performance will be affected", uncompacted)
1091		}
1092	
1093		return result, nil
1094	}
1095	
1096	func (e *Manager) getIndexesFromEpochInternal(ctx context.Context, cs CurrentSnapshot, epoch int) ([]blob.Metadata, error) {
1097		// check if the epoch is old enough to possibly have compacted blobs
1098		epochSettled := cs.isSettledEpochNumber(epoch)
1099		if epochSettled && cs.SingleEpochCompactionSets[epoch] != nil {
1100			return cs.SingleEpochCompactionSets[epoch], nil
1101		}
1102	
1103		// load uncompacted blobs for this epoch, reusing UncompactedEpochSets if we have it.
1104		uncompactedBlobs, ok := cs.UncompactedEpochSets[epoch]
1105		if !ok {
1106			ue, err := blob.ListAllBlobs(ctx, e.st, UncompactedEpochBlobPrefix(epoch))
1107			if err != nil {
1108				return nil, errors.Wrapf(err, "error listing uncompacted indexes for epoch %v", epoch)
1109			}
1110	
1111			uncompactedBlobs = ue
1112		}
1113	
1114		// return uncompacted blobs to the caller while we're compacting them in background
1115		return uncompactedBlobs, nil
1116	}
1117	
1118	func (e *Manager) generateRangeCheckpointFromCommittedState(ctx context.Context, cs CurrentSnapshot, minEpoch, maxEpoch int) error {
1119		contentlog.Log2(ctx, e.log,
1120			"generating range checkpoint",
1121			logparam.Int("minEpoch", minEpoch),
1122			logparam.Int("maxEpoch", maxEpoch))
1123	
1124		completeSet, err := e.getCompleteIndexSetForCommittedState(ctx, cs, minEpoch, maxEpoch)
1125		if err != nil {
1126			return errors.Wrap(err, "unable to get full checkpoint")
1127		}
1128	
1129		if e.timeFunc().After(cs.ValidUntil) {
1130			return errors.New("not generating full checkpoint - the committed state is no longer valid")
1131		}
1132	
1133		if err := e.compact(ctx, blob.IDsFromMetadata(completeSet), rangeCheckpointBlobPrefix(minEpoch, maxEpoch)); err != nil {
1134			return errors.Wrap(err, "unable to compact blobs")
1135		}
1136	
1137		return nil
1138	}
1139	
1140	// UncompactedEpochBlobPrefix returns the prefix for uncompacted blobs of a given epoch.
1141	func UncompactedEpochBlobPrefix(epoch int) blob.ID {
1142		return blob.ID(fmt.Sprintf("%v%v_", UncompactedIndexBlobPrefix, epoch))
1143	}
1144	
1145	func compactedEpochBlobPrefix(epoch int) blob.ID {
1146		return blob.ID(fmt.Sprintf("%v%v_", SingleEpochCompactionBlobPrefix, epoch))
1147	}
1148	
1149	func rangeCheckpointBlobPrefix(epoch1, epoch2 int) blob.ID {
1150		return blob.ID(fmt.Sprintf("%v%v_%v_", RangeCheckpointIndexBlobPrefix, epoch1, epoch2))
1151	}
1152	
1153	// NewManager creates new epoch manager.
1154	func NewManager(st blob.Storage, paramProvider ParametersProvider, compactor CompactionFunc, log *contentlog.Logger, timeNow func() time.Time) *Manager {
1155		return &Manager{
1156			st:                           st,
1157			log:                          log,
1158			compact:                      compactor,
1159			timeFunc:                     timeNow,
1160			paramProvider:                paramProvider,
1161			getCompleteIndexSetTooSlow:   new(int32),
1162			committedStateRefreshTooSlow: new(int32),
1163			writeIndexTooSlow:            new(int32),
1164		}
1165	}

