 71	// epochNumberFromBlobID extracts the epoch number from a string formatted as
 72	// <prefix><epochNumber>_<remainder>.
 73	func epochNumberFromBlobID(blobID blob.ID) (int, bool) {
 74		s := string(blobID)
 75	
 76		if p := strings.IndexByte(s, '_'); p >= 0 {
 77			s = s[0:p]
 78		}
 79	
 80		for s != "" && !unicode.IsDigit(rune(s[0])) {
 81			s = s[1:]
 82		}
 83	
 84		n, err := strconv.Atoi(s)
 85		if err != nil {
 86			return 0, false
 87		}
 88	
 89		return n, true
 90	}
 91	
 92	// epochRangeFromBlobID extracts the range epoch numbers from a string formatted as
 93	// <prefix><epochNumber>_<epochNumber2>_<remainder>.
 94	func epochRangeFromBlobID(blobID blob.ID) (minEpoch, maxEpoch int, ok bool) {
 95		parts := strings.Split(string(blobID), "_")
 96	
 97		//nolint:mnd
 98		if len(parts) < 3 {
 99			return 0, 0, false
100		}
101	
102		first := parts[0]
103		second := parts[1]
104	
105		for first != "" && !unicode.IsDigit(rune(first[0])) {
106			first = first[1:]
107		}
108	
109		n1, err1 := strconv.Atoi(first)
110		n2, err2 := strconv.Atoi(second)
111	
112		return n1, n2, err1 == nil && err2 == nil
113	}
114	
115	func groupByEpochNumber(bms []blob.Metadata) map[int][]blob.Metadata {
116		result := map[int][]blob.Metadata{}
117	
118		for _, bm := range bms {
119			if n, ok := epochNumberFromBlobID(bm.BlobID); ok {
120				result[n] = append(result[n], bm)
121			}
122		}
123	
124		return result
125	}
126	
127	func groupByEpochRanges(bms []blob.Metadata) map[int]map[int][]blob.Metadata {
128		result := map[int]map[int][]blob.Metadata{}
129	
130		for _, bm := range bms {
131			if n1, n2, ok := epochRangeFromBlobID(bm.BlobID); ok {
132				if result[n1] == nil {
133					result[n1] = make(map[int][]blob.Metadata)
134				}
135	
136				result[n1][n2] = append(result[n1][n2], bm)
137			}
138		}
139	
140		return result
141	}
142	
143	func deletionWatermarkFromBlobID(blobID blob.ID) (time.Time, bool) {
144		str := strings.TrimPrefix(string(blobID), string(DeletionWatermarkBlobPrefix))
145	
146		unixSeconds, err := strconv.ParseInt(str, 10, 64)
147		if err != nil {
148			return time.Time{}, false
149		}
150	
151		return time.Unix(unixSeconds, 0), true
152	}
153	
154	// closedIntRange represents a discrete closed-closed [lo, hi] range for ints.
155	// That is, the range includes both lo and hi.
156	type closedIntRange struct {
157		lo, hi int
158	}
159	
160	func (r closedIntRange) length() uint {
161		// any range where lo > hi is empty. The canonical empty representation
162		// is {lo:0, hi: -1}
163		if r.lo > r.hi {
164			return 0
165		}
166	
167		return uint(r.hi - r.lo + 1)
168	}
169	
170	func (r closedIntRange) isEmpty() bool {
171		return r.length() == 0
172	}
173	
174	// constants from the standard math package.
175	const (
176		//nolint:mnd
177		intSize = 32 << (^uint(0) >> 63) // 32 or 64
178	
179		maxInt = 1<<(intSize-1) - 1
180		minInt = -1 << (intSize - 1)
181	)
182	
183	var errInvalidCompactedRange = errors.New("invalid compacted epoch range")
184	
185	func getRangeCompactedRange(cs CurrentSnapshot) closedIntRange {
186		rangeSetsLen := len(cs.LongestRangeCheckpointSets)
187	
188		if rangeSetsLen == 0 {
189			return closedIntRange{lo: 0, hi: -1}
190		}
191	
192		return closedIntRange{
193			lo: cs.LongestRangeCheckpointSets[0].MinEpoch,
194			hi: cs.LongestRangeCheckpointSets[rangeSetsLen-1].MaxEpoch,
195		}
196	}
197	
198	func oldestUncompactedEpoch(cs CurrentSnapshot) (int, error) {
199		rangeCompacted := getRangeCompactedRange(cs)
200	
201		var oldestUncompacted int
202	
203		if !rangeCompacted.isEmpty() {
204			if rangeCompacted.lo != 0 {
205				// range compactions are expected to cover the 0 epoch
206				return -1, errors.Wrapf(errInvalidCompactedRange, "Epoch 0 not included in range compaction, lowest epoch in range compactions: %v", rangeCompacted.lo)
207			}
208	
209			oldestUncompacted = rangeCompacted.hi + 1
210		}
211	
212		oldestUncompacted = getOldestUncompactedAfterEpoch(maps.Keys(cs.SingleEpochCompactionSets), oldestUncompacted)
213	
214		return oldestUncompacted, nil
215	}
216	
217	// filterLowerThan returns a sequence with the elements from s that are greater
218	// or equal than threshold, that is it omits the elements that are strictly less
219	// than threshold.
220	// For example, if s = {0, 3, 5} and threshold is 3, then the resulting sequence
221	// yields {3, 5}.
222	func filterLowerThan[V cmp.Ordered](threshold V, s iter.Seq[V]) iter.Seq[V] {
223		return func(yield func(V) bool) {
224			s(func(v V) bool { // this is the filtering function
225				if v >= threshold {
226					return yield(v) // only yield values >= threshold
227				}
228	
229				return true
230			})
231		}
232	}
233	
234	// getOldestUncompactedAfterEpoch finds the oldest uncompacted epoch given a
235	// sequence of known (single-epoch) compacted epochs. The returned epoch is
236	// greater or equal than the uncompactedCandidateEpoch. For example, suppose
237	// that compacted epochs has { 3, 5, 6, 8 } then the following are the returned
238	// values for uncompactedCandidateEpoch
239	// uncompactedCandidateEpoch < 3 => uncompactedCandidateEpoch
240	// uncompactedCandidateEpoch == 3 => 4
241	// uncompactedCandidateEpoch == 4 => 4
242	// uncompactedCandidateEpoch == 5 or 6 => 7
243	// uncompactedCandidateEpoch == 7 => 7
244	// uncompactedCandidateEpoch == 8 => 9
245	// uncompactedCandidateEpoch > 8 => uncompactedCandidateEpoch.
246	//
247	//nolint:dupword
248	func getOldestUncompactedAfterEpoch(compactedEpochs iter.Seq[int], uncompactedCandidateEpoch int) int {
249		s := slices.Sorted(filterLowerThan(uncompactedCandidateEpoch, compactedEpochs))
250		if len(s) == 0 || uncompactedCandidateEpoch < s[0] {
251			return uncompactedCandidateEpoch
252		}
253	
254		prev := s[0]
255		for _, v := range s[1:] {
256			if v != prev+1 {
257				break
258			}
259	
260			prev = v
261		}
262	
263		return prev + 1
264	}
