  8	
  9	// shouldAdvance determines if the current epoch should be advanced based on set of blobs in it.
 10	//
 11	// Epoch will be advanced if it's been more than 'minEpochDuration' between earliest and
 12	// most recent write AND at least one of the criteria has been met:
 13	//
 14	// - number of blobs in the epoch exceeds 'countThreshold'
 15	// - total size of blobs in the epoch exceeds 'totalSizeBytesThreshold'.
 16	func shouldAdvance(bms []blob.Metadata, minEpochDuration time.Duration, countThreshold int, totalSizeBytesThreshold int64) bool {
 17		if len(bms) == 0 {
 18			return false
 19		}
 20	
 21		var (
 22			minTime   = bms[0].Timestamp
 23			maxTime   = bms[0].Timestamp
 24			totalSize = int64(0)
 25		)
 26	
 27		for _, bm := range bms {
 28			if bm.Timestamp.Before(minTime) {
 29				minTime = bm.Timestamp
 30			}
 31	
 32			if bm.Timestamp.After(maxTime) {
 33				maxTime = bm.Timestamp
 34			}
 35	
 36			totalSize += bm.Length
 37		}
 38	
 39		// not enough time between first and last write in an epoch.
 40		if maxTime.Sub(minTime) < minEpochDuration {
 41			return false
 42		}
 43	
 44		if len(bms) >= countThreshold {
 45			return true
 46		}
 47	
 48		if totalSize >= totalSizeBytesThreshold {
 49			return true
 50		}
 51	
 52		return false
 53	}
