     1	package snapshotfs
     2	
     3	import (
     4		"context"
     5		"path"
     6		"runtime"
     7		"sync"
     8	
     9		"github.com/pkg/errors"
    10	
    11		"github.com/kopia/kopia/fs"
    12		"github.com/kopia/kopia/internal/bigmap"
    13		"github.com/kopia/kopia/internal/workshare"
    14		"github.com/kopia/kopia/repo/object"
    15	)
    16	
    17	const walkersPerCPU = 4
    18	
    19	// EntryCallback is invoked when walking the tree of snapshots.
    20	type EntryCallback func(ctx context.Context, entry fs.Entry, oid object.ID, entryPath string) error
    21	
    22	// TreeWalker processes snapshot filesystem trees by invoking the provided callback
    23	// once for each object found in the tree.
    24	type TreeWalker struct {
    25		options TreeWalkerOptions
    26	
    27		enqueued *bigmap.Set
    28		wp       *workshare.Pool[any]
    29	
    30		mu sync.Mutex
    31		// +checklocks:mu
    32		numErrors int
    33		// +checklocks:mu
    34		errors []error
    35	}
    36	
    37	func oidOf(e fs.Entry) object.ID {
    38		if h, ok := e.(object.HasObjectID); ok {
    39			return h.ObjectID()
    40		}
    41	
    42		return object.EmptyID
    43	}
    44	
    45	// ReportError reports the error.
    46	func (w *TreeWalker) ReportError(ctx context.Context, entryPath string, err error) {
    47		w.mu.Lock()
    48		defer w.mu.Unlock()
    49	
    50		repoFSLog(ctx).Errorf("error processing %v: %v", entryPath, err)
    51	
    52		// Record one error if we can't get too many errors so that at least that one
    53		// can be returned if it's the only one.
    54		if len(w.errors) < w.options.MaxErrors || (w.options.MaxErrors <= 0 && len(w.errors) == 0) {
    55			w.errors = append(w.errors, err)
    56		}
    57	
    58		w.numErrors++
    59	}
    60	
    61	// GetErrors returns a copy of the list of errors found during the tree walk, as well
    62	// as the total count of errors encountered.
    63	func (w *TreeWalker) GetErrors() (errs []error, numErrors int) {
    64		w.mu.Lock()
    65		defer w.mu.Unlock()
    66	
    67		return append([]error{}, w.errors...), w.numErrors
    68	}
    69	
    70	// Err returns the error encountered when walking the tree.
    71	func (w *TreeWalker) Err() error {
    72		w.mu.Lock()
    73		defer w.mu.Unlock()
    74	
    75		switch w.numErrors {
    76		case 0:
    77			return nil
    78		case 1:
    79			return w.errors[0]
    80		default:
    81			return errors.Errorf("encountered %v errors", w.numErrors)
    82		}
    83	}
    84	
    85	// TooManyErrors reports true if there are too many errors already reported.
    86	func (w *TreeWalker) TooManyErrors() bool {
    87		if w.options.MaxErrors <= 0 {
    88			// unlimited
    89			return false
    90		}
    91	
    92		w.mu.Lock()
    93		defer w.mu.Unlock()
    94	
    95		return w.numErrors >= w.options.MaxErrors
    96	}
    97	
    98	func (w *TreeWalker) alreadyProcessed(ctx context.Context, e fs.Entry) bool {
    99		var idbuf [128]byte
   100	
   101		return !w.enqueued.Put(ctx, oidOf(e).Append(idbuf[:0]))
   102	}
   103	
   104	func (w *TreeWalker) processEntry(ctx context.Context, e fs.Entry, entryPath string) {
   105		if ec := w.options.EntryCallback; ec != nil {
   106			err := ec(ctx, e, oidOf(e), entryPath)
   107			if err != nil {
   108				w.ReportError(ctx, entryPath, err)
   109				return
   110			}
   111		}
   112	
   113		if dir, ok := e.(fs.Directory); ok {
   114			w.processDirEntry(ctx, dir, entryPath)
   115		}
   116	}
   117	
   118	func (w *TreeWalker) processDirEntry(ctx context.Context, dir fs.Directory, entryPath string) {
   119		var ag workshare.AsyncGroup[any]
   120		defer ag.Close()
   121	
   122		iter, err := dir.Iterate(ctx)
   123		if err != nil {
   124			w.ReportError(ctx, entryPath, errors.Wrap(err, "error reading directory"))
   125	
   126			return
   127		}
   128	
   129		defer iter.Close()
   130	
   131		ent, err := iter.Next(ctx)
   132		for ent != nil {
   133			ent2 := ent
   134	
   135			if w.TooManyErrors() {
   136				break
   137			}
   138	
   139			if !w.alreadyProcessed(ctx, ent2) {
   140				childPath := path.Join(entryPath, ent2.Name())
   141	
   142				if ag.CanShareWork(w.wp) {
   143					ag.RunAsync(w.wp, func(_ *workshare.Pool[any], _ any) {
   144						w.processEntry(ctx, ent2, childPath)
   145					}, nil)
   146				} else {
   147					w.processEntry(ctx, ent2, childPath)
   148				}
   149			}
