     1	// Package listcache defines a blob.Storage wrapper that caches results of list calls
     2	// for short duration of time.
     3	package listcache
     4	
     5	import (
     6		"context"
     7		"encoding/json"
     8		"slices"
     9		"strings"
    10		"time"
    11	
    12		"github.com/pkg/errors"
    13	
    14		"github.com/kopia/kopia/internal/clock"
    15		"github.com/kopia/kopia/internal/gather"
    16		"github.com/kopia/kopia/internal/hmac"
    17		"github.com/kopia/kopia/repo/blob"
    18		"github.com/kopia/kopia/repo/logging"
    19	)
    20	
    21	var log = logging.Module("listcache")
    22	
    23	type listCacheStorage struct {
    24		blob.Storage
    25		cacheStorage  blob.Storage
    26		cacheDuration time.Duration
    27		cacheTimeFunc func() time.Time
    28		hmacSecret    []byte
    29		prefixes      []blob.ID
    30	}
    31	
    32	type cachedList struct {
    33		ExpireAfter time.Time       `json:"expireAfter"`
    34		Blobs       []blob.Metadata `json:"blobs"`
    35	}
    36	
    37	func (s *listCacheStorage) saveListToCache(ctx context.Context, prefix blob.ID, cl *cachedList) {
    38		data, err := json.Marshal(cl)
    39		if err != nil {
    40			log(ctx).Debugw("unable to marshal list cache entry", "prefix", prefix, "err", err)
    41			return
    42		}
    43	
    44		var b gather.WriteBuffer
    45		defer b.Close()
    46	
    47		hmac.Append(gather.FromSlice(data), s.hmacSecret, &b)
    48	
    49		if err := s.cacheStorage.PutBlob(ctx, prefix, b.Bytes(), blob.PutOptions{}); err != nil {
    50			log(ctx).Debugw("unable to persist list cache entry", "prefix", prefix, "err", err)
    51		}
    52	}
    53	
    54	func (s *listCacheStorage) readBlobsFromCache(ctx context.Context, prefix blob.ID) *cachedList {
    55		cl := &cachedList{}
    56	
    57		var data gather.WriteBuffer
    58		defer data.Close()
    59	
    60		if err := s.cacheStorage.GetBlob(ctx, prefix, 0, -1, &data); err != nil {
    61			return nil
    62		}
    63	
    64		var verified gather.WriteBuffer
    65		defer verified.Close()
    66	
    67		if err := hmac.VerifyAndStrip(data.Bytes(), s.hmacSecret, &verified); err != nil {
    68			log(ctx).Warnf("invalid list cache HMAC for %v, ignoring", prefix)
    69			return nil
    70		}
    71	
    72		if err := json.NewDecoder(verified.Bytes().Reader()).Decode(&cl); err != nil {
    73			log(ctx).Warnf("can't unmarshal cached list results for %v, ignoring", prefix)
    74			return nil
    75		}
    76	
    77		if s.cacheTimeFunc().Before(cl.ExpireAfter) {
    78			return cl
    79		}
    80	
    81		// list cache expired
    82		return nil
    83	}
    84	
    85	// ListBlobs implements blob.Storage and caches previous list results for a given prefix.
    86	func (s *listCacheStorage) ListBlobs(ctx context.Context, prefix blob.ID, cb func(blob.Metadata) error) error {
    87		if !s.isCachedPrefix(prefix) {
    88			//nolint:wrapcheck
    89			return s.Storage.ListBlobs(ctx, prefix, cb)
    90		}
    91	
    92		cached := s.readBlobsFromCache(ctx, prefix)
    93		if cached == nil {
    94			all, err := blob.ListAllBlobs(ctx, s.Storage, prefix)
    95			if err != nil {
    96				//nolint:wrapcheck
    97				return err
    98			}
    99	
   100			cached = &cachedList{
   101				ExpireAfter: s.cacheTimeFunc().Add(s.cacheDuration),
   102				Blobs:       all,
   103			}
   104	
   105			s.saveListToCache(ctx, prefix, cached)
   106		}
   107	
   108		for _, v := range cached.Blobs {
   109			if err := cb(v); err != nil {
   110				return err
   111			}
   112		}
   113	
   114		return nil
   115	}
   116	
   117	// PutBlob implements blob.Storage and writes markers into local cache for all successful writes.
   118	func (s *listCacheStorage) PutBlob(ctx context.Context, blobID blob.ID, data blob.Bytes, opts blob.PutOptions) error {
   119		err := s.Storage.PutBlob(ctx, blobID, data, opts)
   120		s.invalidateAfterUpdate(ctx, blobID)
   121	
   122		//nolint:wrapcheck
   123		return err
   124	}
   125	
   126	func (s *listCacheStorage) FlushCaches(ctx context.Context) error {
   127		if err := s.Storage.FlushCaches(ctx); err != nil {
   128			return errors.Wrap(err, "error flushing caches")
   129		}
   130	
   131		return errors.Wrap(blob.DeleteMultiple(ctx, s.cacheStorage, s.prefixes, len(s.prefixes)), "error deleting cached lists")
   132	}
   133	
   134	// DeleteBlob implements blob.Storage and writes markers into local cache for all successful deletes.
   135	func (s *listCacheStorage) DeleteBlob(ctx context.Context, blobID blob.ID) error {
   136		err := s.Storage.DeleteBlob(ctx, blobID)
   137		s.invalidateAfterUpdate(ctx, blobID)
   138	
   139		//nolint:wrapcheck
   140		return err
   141	}
   142	
   143	func (s *listCacheStorage) isCachedPrefix(prefix blob.ID) bool {
   144		return slices.Contains(s.prefixes, prefix)
   145	}
   146	
   147	func (s *listCacheStorage) invalidateAfterUpdate(ctx context.Context, blobID blob.ID) {
   148		for _, p := range s.prefixes {
   149			if strings.HasPrefix(string(blobID), string(p)) {
   150				if err := s.cacheStorage.DeleteBlob(ctx, p); err != nil {
   151					log(ctx).Debugw("unable to delete cached list", "prefix", p, "err", err)
   152				}
   153			}
   154		}
   155	}
   156	
   157	// NewWrapper returns new wrapper that ensures list consistency with local writes for the given set of blob prefixes.
   158	// It leverages the provided local cache storage to maintain markers keeping track of recently created and deleted blobs.
   159	func NewWrapper(st, cacheStorage blob.Storage, prefixes []blob.ID, hmacSecret []byte, duration time.Duration) blob.Storage {
   160		if cacheStorage == nil {
   161			return st
   162		}
   163	
   164		return &listCacheStorage{
   165			Storage:       st,
   166			cacheStorage:  cacheStorage,
   167			prefixes:      prefixes,
   168			cacheTimeFunc: clock.Now,
   169			hmacSecret:    hmacSecret,
   170			cacheDuration: duration,
   171		}
   172	}
   173	
   174	var _ blob.Storage = (*listCacheStorage)(nil)
