  1	package epoch
  2	
  3	import (
  4		"github.com/kopia/kopia/repo/blob"
  5	)
  6	
  7	// RangeMetadata represents a range of indexes for [min,max] epoch range. Both min and max are inclusive.
  8	type RangeMetadata struct {
  9		MinEpoch int             `json:"min"`
 10		MaxEpoch int             `json:"max"`
 11		Blobs    []blob.Metadata `json:"blobs"`
 12	}
 13	
 14	func findLongestRangeCheckpoint(ranges []*RangeMetadata) []*RangeMetadata {
 15		byMin := map[int][]*RangeMetadata{}
 16	
 17		for _, r := range ranges {
 18			byMin[r.MinEpoch] = append(byMin[r.MinEpoch], r)
 19		}
 20	
 21		return findLongestRangeCheckpointStartingAt(0, byMin, make(map[int][]*RangeMetadata))
 22	}
 23	
 24	func findLongestRangeCheckpointStartingAt(startEpoch int, byMin, memo map[int][]*RangeMetadata) []*RangeMetadata {
 25		l, ok := memo[startEpoch]
 26		if ok {
 27			return l
 28		}
 29	
 30		var (
 31			longest         = 0
 32			longestMetadata []*RangeMetadata
 33		)
 34	
 35		for _, cp := range byMin[startEpoch] {
 36			combined := append([]*RangeMetadata{cp}, findLongestRangeCheckpointStartingAt(cp.MaxEpoch+1, byMin, memo)...)
 37	
 38			if m := combined[len(combined)-1].MaxEpoch; (m > longest) || (m == longest && len(combined) < len(longestMetadata)) {
 39				longest = m
 40				longestMetadata = combined
 41			}
 42		}
 43	
 44		memo[startEpoch] = longestMetadata
 45	
 46		return longestMetadata
 47	}
 40		return LogRetentionOptions{
 41			MaxTotalSize: 1 << 30,             // keep no more than 1 GiB logs
 42			MaxAge:       30 * 24 * time.Hour, // no more than 30 days of data
 43			MaxCount:     10000,               // no more than 10K logs
 44		}
 45	}
 46	
 47	// CleanupLogs deletes old logs blobs beyond certain age, total size or count.
 48	func CleanupLogs(ctx context.Context, rep repo.DirectRepositoryWriter, opt LogRetentionOptions) (*maintenancestats.CleanupLogsStats, error) {
 49		ctx = contentlog.WithParams(ctx,
 50			logparam.String("span:cleanup-logs", contentlog.RandomSpanID()))
 51	
 52		log := rep.LogManager().NewLogger("maintenance-cleanup-logs")
 53	
 54		if opt.TimeFunc == nil {
 55			opt.TimeFunc = clock.Now
 56		}
 57	
 58		allLogBlobs, err := blob.ListAllBlobs(ctx, rep.BlobStorage(), repodiag.LogBlobPrefix)
 59		if err != nil {
 60			return nil, errors.Wrap(err, "error listing logs")
 61		}
 62	
 63		// sort by time so that most recent are first
 64		sort.Slice(allLogBlobs, func(i, j int) bool {
 65			return allLogBlobs[i].Timestamp.After(allLogBlobs[j].Timestamp)
 66		})
 67	
 68		var retainedSize uint64
 69	
 70		deletePosition := len(allLogBlobs)
 71	
 72		for i, bm := range allLogBlobs {
 73			bmlen := maintenancestats.ToUint64(bm.Length)
 74	
 75			if opt.MaxTotalSize > 0 && retainedSize+bmlen > uint64(opt.MaxTotalSize) {
 76				deletePosition = i
 77				break
 78			}
 79	
 80			if i >= opt.MaxCount && opt.MaxCount > 0 {
 81				deletePosition = i
 82				break
 83			}
 84	
 85			if age := opt.TimeFunc().Sub(bm.Timestamp); age > opt.MaxAge && opt.MaxAge != 0 {
 86				deletePosition = i
 87				break
 88			}
 89	
 90			retainedSize += bmlen
 91		}
 92	
 93		toDelete := allLogBlobs[deletePosition:]
 94	
 95		var toDeleteSize uint64
 96		for _, bm := range toDelete {
 97			toDeleteSize += maintenancestats.ToUint64(bm.Length)
 98		}
 99	
100		result := &maintenancestats.CleanupLogsStats{
101			RetainedBlobCount: maintenancestats.ToUint64(deletePosition),
102			RetainedBlobSize:  retainedSize,
103			ToDeleteBlobCount: maintenancestats.ToUint64(len(toDelete)),
104			ToDeleteBlobSize:  toDeleteSize,
105			DeletedBlobCount:  0,
106			DeletedBlobSize:   0,
107		}
108	
109		contentlog.Log1(ctx, log, "Clean up logs", result)
110	
111		if !opt.DryRun {
112			for _, bm := range toDelete {
113				if err := rep.BlobStorage().DeleteBlob(ctx, bm.BlobID); err != nil {
114					return nil, errors.Wrapf(err, "error deleting log %v", bm.BlobID)
115				}
116			}
117	
118			result.DeletedBlobCount = result.ToDeleteBlobCount
119			result.DeletedBlobSize = result.ToDeleteBlobSize
120		}
121	
122		return result, nil
123	}
 60	}
 61	
 62	func (s *srvMaintenance) beforeRun() {
 63		s.mu.Lock()
 64		defer s.mu.Unlock()
 65	
 66		// make sure we're not scheduling next maintenance until we refresh
 67		s.cachedNextMaintenanceTime = time.Time{}
 68	}
 69	
 70	func (s *srvMaintenance) afterFailedRun() {
 71		s.mu.Lock()
 72		defer s.mu.Unlock()
 73	
 74		// make sure we don't run maintenance too often
 75		s.nextMaintenanceNoEarlierThan = clock.Now().Add(s.minMaintenanceInterval)
 76	}
 77	
 78	func (s *srvMaintenance) refresh(ctx context.Context, notify bool) {
 79		if notify {
 80			defer s.srv.refreshScheduler("maintenance schedule changed")
 81		}
 82	
 83		s.mu.Lock()
 84		defer s.mu.Unlock()
 85	
 86		if err := s.refreshLocked(ctx); err != nil {
 87			userLog(ctx).Debugw("unable to refresh maintenance manager", "err", err)
 88		}
 89	}
 90	
 91	func (s *srvMaintenance) refreshLocked(ctx context.Context) error {
 92		nmt, err := maintenance.TimeToAttemptNextMaintenance(ctx, s.dr)
 93		if err != nil {
 94			return errors.Wrap(err, "unable to get next maintenance time")
 95		}
 96	
