package policy

import (
	"testing"
	"time"

	"github.com/kopia/kopia/fs"
	"github.com/kopia/kopia/snapshot"
)

func oi(n int) *OptionalInt { v := OptionalInt(n); return &v }

func TestZZAuditWeeklyMonthly(t *testing.T) {
	for _, tc := range []struct {
		name string
		rp   RetentionPolicy
	}{
		{"weekly6 only", RetentionPolicy{KeepWeekly: oi(6)}},
		{"weekly6+monthly2", RetentionPolicy{KeepWeekly: oi(6), KeepMonthly: oi(2)}},
	} {
		var ms []*snapshot.Manifest
		for d := time.Date(2026, 1, 4, 12, 0, 0, 0, time.UTC); !d.After(time.Date(2026, 2, 8, 12, 0, 0, 0, time.UTC)); d = d.AddDate(0, 0, 7) {
			ms = append(ms, &snapshot.Manifest{StartTime: fs.UTCTimestampFromTime(d)})
		}
		tc.rp.ComputeRetentionReasons(ms)
		for _, m := range ms {
			t.Logf("%v: %v %v", tc.name, m.StartTime.Format("2006-01-02"), m.RetentionReasons)
		}
	}
}

func TestZZAuditWeeklyTZ(t *testing.T) {
	rp := RetentionPolicy{KeepWeekly: oi(4), KeepDaily: oi(1)}
	var ms []*snapshot.Manifest
	for _, s := range []string{"2026-11-09T03:00:00Z", "2026-11-15T20:00:00Z", "2026-11-16T03:00:00Z", "2026-11-22T20:00:00Z", "2026-11-23T03:00:00Z"} {
		d, _ := time.Parse(time.RFC3339, s)
		ms = append(ms, &snapshot.Manifest{StartTime: fs.UTCTimestampFromTime(d)})
	}
	rp.ComputeRetentionReasons(ms)
	for _, m := range ms {
		t.Logf("TZ=%v %v %v", time.Local, m.StartTime.Format(time.RFC3339), m.RetentionReasons)
	}
}
EOF
