package maintenance_test

import (
	"crypto/rand"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/kopia/kopia/fs"
	"github.com/kopia/kopia/internal/faketime"
	"github.com/kopia/kopia/internal/repotesting"
	"github.com/kopia/kopia/repo"
	"github.com/kopia/kopia/repo/format"
	"github.com/kopia/kopia/repo/maintenance"
	"github.com/kopia/kopia/repo/object"
	"github.com/kopia/kopia/snapshot"
	"github.com/kopia/kopia/snapshot/snapshotmaintenance"
)

func zzWriteObject(t *testing.T, env *repotesting.Environment) object.ID {
	t.Helper()

	data := make([]byte, 1<<20)
	_, _ = rand.Read(data)

	w := env.RepositoryWriter.NewObjectWriter(t.Context(), object.WriterOptions{MetadataCompressor: "zstd-fastest"})
	_, err := w.Write(data)
	require.NoError(t, err)

	oid, err := w.Result()
	require.NoError(t, err)
	require.NoError(t, w.Close())

	return oid
}

func TestZZAuditItem6(t *testing.T) {
	for _, forged := range []bool{false, true} {
		ta := faketime.NewClockTimeWithOffset(0)
		opt := func(o *repo.Options) { o.TimeNowFunc = ta.NowFunc() }

		ctx, env := repotesting.NewEnvironment(t, format.FormatVersion3, repotesting.Options{OpenOptions: opt})

		mp, err := maintenance.GetParams(ctx, env.RepositoryWriter)
		require.NoError(t, err)

		mp.Owner = env.RepositoryWriter.ClientOptions().UsernameAtHost()
		require.NoError(t, maintenance.SetParams(ctx, env.RepositoryWriter, mp))

		oid := zzWriteObject(t, env)
		src := snapshot.SourceInfo{Host: "h", UserName: "u", Path: "/p"}

		if !forged {
			_, err = snapshot.SaveSnapshot(ctx, env.RepositoryWriter, &snapshot.Manifest{
				Source:    src,
				StartTime: fs.UTCTimestampFromTime(ta.NowFunc()()),
				RootEntry: &snapshot.DirEntry{Name: "f", Type: snapshot.EntryTypeFile, ObjectID: oid, FileSize: 1 << 20},
			})
			require.NoError(t, err)
		} else {
			// same manifest, but with a field the reader cannot unmarshal (startTime as a number).
			_, err = env.RepositoryWriter.PutManifest(ctx,
				map[string]string{"type": "snapshot", "hostname": "h", "username": "u", "path": "/p"},
				map[string]any{
					"source":    src,
					"startTime": 12345,
					"rootEntry": &snapshot.DirEntry{Name: "f", Type: snapshot.EntryTypeFile, ObjectID: oid, FileSize: 1 << 20},
				})
			require.NoError(t, err)
		}

		require.NoError(t, env.RepositoryWriter.Flush(ctx))

		for day := 1; day <= 4; day++ {
			ta.Advance(25 * time.Hour)
			env.MustReopen(t, opt)

			merr := snapshotmaintenance.Run(ctx, env.RepositoryWriter, maintenance.ModeFull, false, maintenance.SafetyFull)

			fresh := env.MustOpenAnother(t, opt)
			ids, lerr := snapshot.ListSnapshotManifests(ctx, fresh, nil, nil)
			require.NoError(t, lerr)

			r, oerr := fresh.OpenObject(ctx, oid)
			if oerr == nil {
				r.Close()
			}

			t.Logf("forged=%v day %v: maintenanceErr=%v manifestsListed=%v objectReadable=%v", forged, day, merr, len(ids), oerr == nil)
		}
	}
}
EOF
