    elif 'xn0_' in line and 'PutBlob' in line: m='index blob written'
    if m: out.append((small,m))
prev=0
for s,m in out[-22:]:
    print('  +%5d small files completed, then: %s'%(s-prev,m)); prev=s
print('  total small files completed in log:',small)
EOF

